const SECTIONS = [
  ["reports", "Report Settings", "إعدادات التقارير"],
  ["processes", "Process Templates", "قوالب الإجراءات"],
  ["surveys", "Survey Templates", "قوالب الاستبيان"],
  ["rewards", "Rewards, Penalties & Evaluation", "المكافآت والجزاءات والتقييم"],
  ["appraisal", "Monthly Appraisal", "التقييم الشهري"],
  ["suitability", "Suitability & Recommendations", "الملاءمة والتوصيات"],
  ["leadership", "Shift Leadership & Staffing", "قيادة الشيفت والتوظيف"],
  ["succession", "Succession Paths & Competencies", "مسارات الخلافة والكفاءات"],
  ["permissions", "Permissions & Approvals", "الصلاحيات والاعتمادات"],
];

const EMPTY_REPORT = {
  active: false, branches: [], required: false, completionDeadlineMinutes: 0, approvalRole: "MANAGER", requiredFields: [],
  attachments: { required: false, minimumCount: 0, allowedTypes: [] }, fastEverythingPlannedEnabled: false,
  surveyRequired: false, unresolvedIssuesBlockApproval: false,
  reopen: { allowed: false, reasonRequired: true, roles: [] },
  locking: { lockOnApproval: true, manualLockAllowed: false, roles: [] },
};

const EMPTY_CONFIG = {
  reports: Object.fromEntries(REPORT_TYPES.map((type) => [type, structuredClone(EMPTY_REPORT)])),
  processTemplates: [], surveyTemplates: [],
  rewards: {
    active: false, attendanceScoringEnabled: false, onTimeBonus: 0, latenessBands: [], absenceDeduction: 0, performanceLevels: [],
    maximumPositivePointsPerEvent: 0, maximumNegativePointsPerEvent: 0, maximumMonthlyEventBonus: 0, maximumMonthlyEventPenalty: 0,
    useReportTypeValues: false, reportTypeValues: { TRIP: 0, BIRTHDAY: 0, SHIFT_LEADERSHIP: 0 },
    teamLeaderValues: { enabled: false, multiplier: 1 }, attendanceMayCreateAdditionalEventImpact: false,
    roles: { propose: [], approve: [], reject: [], reopen: [] },
  },
  evaluation: {
    rules: { defaultScoreMode: "FULL_UNREVIEWED", penaltyDeduction: 0, guidanceDeduction: 0, requireReasonForDeduction: true, requireReviewBeforeClose: true },
    criteriaVersionId: null, criteria: [],
  },
  monthlyAppraisal: {
    active: false, aggregationMethod: "AVERAGE_PERCENTAGE", eventAdjustmentTreatment: "SEPARATE_COMPONENT",
    monthlyPositiveCap: 0, monthlyNegativeCap: 0, finalScoreMinimum: 0, finalScoreMaximum: 0, performanceBands: [],
    minimumDataCoverage: { unit: "PERCENTAGE", value: 0 },
    workflow: { provisionalAllowed: false, reviewRequired: true, approvalRequired: true, lockOnApproval: true, reopenReasonRequired: true, reviewRoles: [], approvalRoles: [], reopenRoles: [] },
    recalculation: { onSourceChange: "DRAFT_ONLY", approvedRecordBehavior: "PRESERVE" },
    formulaVersionId: null, formulaParameters: {}, sourceFormula: { code: "", label: "", effectiveFrom: "", effectiveTo: "", config: {} },
  },
  suitability: SUITABILITY_PROFILES.map((code) => ({
    code, label: code.replaceAll("_", " "), active: false, rollingWindowDays: 0, maximumRecentEvents: 0, minimumEvents: 0,
    weightingMode: "PERCENTAGE", weights: { punctuality: 0, performance: 0, guestFeedback: 0, processReliability: 0, leadershipProblemResolution: 0 },
    thresholds: [], cautionRules: [], notRecommendedRules: [], decay: { mode: "NONE", halfLifeDays: null },
    override: { allowed: false, reasonRequired: true, roles: [] }, recalculation: { trigger: "ON_SOURCE_CHANGE", schedule: null },
  })),
  shiftLeadership: {
    active: false, enabledBranches: [], requiredWeekdays: [], selectedDates: [], busyPeriods: [], holidays: [], shiftCodes: [],
    teamLeaderRequired: false, primaryLeaderCount: 0, deputyAllowed: false, requiredReadyTimeOffsetMinutes: 0,
    automaticReportCreation: false, reportDueTime: null, approvalRole: "MANAGER",
    replacement: { allowed: false, reasonRequired: true, roles: [] }, preventSelfApproval: true, assignmentQualifiesAsSuccessionEvidence: false,
  },
  staffing: {
    active: false, maximumResponsibleBirthdayHosts: 0, primaryTripTeamLeaders: 0, backupStaffAllowed: false,
    suggestedTripShiftCodes: [], timeOverlap: { allowed: false, toleranceMinutes: 0 }, requireAvailability: true,
    conflictWarningsEnabled: true, override: { allowed: false, roles: [], reasonRequired: true },
  },
  succession: { paths: [], competencies: [], readinessLevels: [], reviewFrequencyOptions: [], developmentActionTypes: [], developmentStatuses: [] },
  permissions: {
    settingsRoles: [], reportProposeRoles: [], reportApproveRoles: [], adjustmentProposeRoles: [], adjustmentApproveRoles: [],
    adjustmentRejectRoles: [], adjustmentReopenRoles: [], suitabilityOverrideRoles: [], staffingOverrideRoles: [],
    requireSecondReviewerForLinkedPublisher: false,
  },
};

function isObject(value) { return value && typeof value === "object" && !Array.isArray(value); }
function mergeDefaults(base, value) {
  if (Array.isArray(base)) return Array.isArray(value) ? structuredClone(value) : structuredClone(base);
  if (!isObject(base)) return value === undefined ? base : value;
  const source = isObject(value) ? value : {};
  return Object.fromEntries(Object.keys(base).map((key) => [key, mergeDefaults(base[key], source[key])]).concat(Object.keys(source).filter((key) => !(key in base)).map((key) => [key, structuredClone(source[key])])));
}
function normalizeConfig(value) {
  const normalized = mergeDefaults(EMPTY_CONFIG, value);
  normalized.suitability = SUITABILITY_PROFILES.map((code) => mergeDefaults(EMPTY_CONFIG.suitability.find((item) => item.code === code), (value?.suitability || []).find((item) => item.code === code)));
  normalized.permissions.requireSecondReviewerForLinkedPublisher = true;
  return normalized;
}
function atPath(source, path) { return path.reduce((value, key) => value?.[key], source); }
function withPath(source, path, value) {
  const next = structuredClone(source); let target = next;
  path.slice(0, -1).forEach((key) => { target = target[key]; });
  target[path.at(-1)] = value;
  return next;
}
function moveItem(items, index, delta, orderKey) {
  const nextIndex = index + delta;
  if (nextIndex < 0 || nextIndex >= items.length) return items;
  const next = [...items]; [next[index], next[nextIndex]] = [next[nextIndex], next[index]];
  return orderKey ? next.map((item, itemIndex) => ({ ...item, [orderKey]: (itemIndex + 1) * 10 })) : next;
}
function list(value) { return Array.isArray(value) ? value : value ? [String(value)] : []; }
function branchCode(item) { return typeof item === "string" ? item : String(item?.code || item?.branch || item?.id || ""); }
function today() { const date = new Date(); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10); }
function itemCode(prefix) { return `${prefix}_${Date.now().toString(36).toUpperCase()}`; }

function validateConfig(config) {
  const errors = [];
  const ranges = config.rewards.latenessBands.filter((item) => item.active !== false).sort((a, b) => Number(a.minimumMinutes) - Number(b.minimumMinutes));
  ranges.forEach((range, index) => {
    if (Number(range.minimumMinutes) > Number(range.maximumMinutes)) errors.push(`Lateness range ${range.code || index + 1} has a minimum above its maximum.`);
    if (index && Number(range.minimumMinutes) <= Number(ranges[index - 1].maximumMinutes)) errors.push(`Lateness range ${range.code || index + 1} overlaps another active range.`);
  });
  config.monthlyAppraisal.performanceBands.filter((item) => item.active !== false).forEach((band, index) => {
    if (Number(band.minimum) > Number(band.maximum)) errors.push(`Performance band ${band.code || index + 1} has an invalid range.`);
  });
  config.processTemplates.filter((item) => item.active).forEach((template) => {
    if (!template.steps?.some((step) => step.active !== false)) errors.push(`Active process template ${template.code} needs at least one active step.`);
  });
  config.surveyTemplates.filter((item) => item.active).forEach((template) => {
    if (!template.questions?.length) errors.push(`Active survey template ${template.code} needs at least one question.`);
    template.questions?.filter((question) => question.active !== false).forEach((question) => { if (!question.choices?.some((choice) => choice.active !== false)) errors.push(`Survey question ${question.code} needs an active choice.`); });
  });
  config.suitability.forEach((profile) => {
    if (profile.weightingMode === "PERCENTAGE") {
      const total = Object.values(profile.weights).reduce((sum, value) => sum + Number(value || 0), 0);
      if (total !== 100) errors.push(`${profile.code} percentage weights total ${total}%, not 100%.`);
    }
    profile.thresholds.filter((item) => item.active !== false).forEach((threshold) => { if (Number(threshold.minimum) > Number(threshold.maximum)) errors.push(`${profile.code} threshold ${threshold.status} has an invalid range.`); });
  });
  return errors;
}

export default function PerformanceSettingsWorkspace({ isArabic: languageOverride,section,embedded=false }) {
  const canConfigure = usePermission('settings.configure');
  const { isArabic: contextArabic } = useI18n();
  const isArabic = typeof languageOverride === "boolean" ? languageOverride : contextArabic;
  const t = useCallback((en, ar) => isArabic ? ar : en, [isArabic]);
  const [scope, setScope] = useState("GLOBAL");
  const [globalAccessible, setGlobalAccessible] = useState(false);
  const [state, setState] = useState(null);
  const [editing, setEditing] = useState(false);
  const [config, setConfig] = useState(() => normalizeConfig());
  const [baseline, setBaseline] = useState(() => normalizeConfig());
  const [activeSection, setActiveSection] = useState(section||"reports");
  useEffect(() => {
    const requested = new URLSearchParams(window.location.search).get("section");
    if (!section&&SECTIONS.some(([key]) => key === requested)) setActiveSection(requested);
  }, []);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [draftReason, setDraftReason] = useState("");
  const [publishOpen, setPublishOpen] = useState(false);
  const [publishReason, setPublishReason] = useState("");
  const [publishDate, setPublishDate] = useState(today());
  const [resetOpen, setResetOpen] = useState(false);
  const [resetReason, setResetReason] = useState("");
  const [resetDate, setResetDate] = useState(today());
  const tabId = useId();

  const applyState = useCallback((nextState) => {
    const nextConfig = normalizeConfig(nextState?.draft?.value || nextState?.effective?.value);
    const returnedScope = nextState?.scope?.type === "BRANCH" ? branchCode(nextState.scope.branch) : nextState?.scope?.type === "GLOBAL" ? "GLOBAL" : null;
    setState(nextState); setEditing(Boolean(nextState?.draft)); if (nextState?.scope?.type === "GLOBAL") setGlobalAccessible(true); if (returnedScope) setScope(returnedScope); setConfig(nextConfig); setBaseline(structuredClone(nextConfig));
  }, []);
  const load = useCallback(async (nextScope) => {
    setBusy(true); setError(""); setNotice("");
    try {
      const query = nextScope ? `?scope=${encodeURIComponent(nextScope)}` : "";
      const payload = await fetch(`/api/operations/performance-settings${query}`, { cache: "no-store" }).then((response) => readApiResponse(response));
      applyState(payload.state);
    } catch (requestError) { setError(requestError.message); }
    finally { setBusy(false); }
  }, [applyState]);
  useEffect(() => { load(); }, [load]);

  const dirty = useMemo(() => JSON.stringify(config) !== JSON.stringify(baseline), [config, baseline]);
  const unsavedDraft = dirty || Boolean(draftReason.trim()) || (editing && !state?.draft);
  useDraftRegistration({ label: t("Performance configuration", "قواعد الأداء"), dirty:unsavedDraft || Boolean(publishReason.trim()) || Boolean(resetReason.trim()), discard: () => { setConfig(structuredClone(baseline)); setDraftReason(""); setPublishReason(""); setResetReason(""); setEditing(Boolean(state?.draft)); setError(""); setNotice(""); } });
  const validation = useMemo(() => validateConfig(config), [config]);
  const update = useCallback((path, value) => setConfig((current) => withPath(current, path, value)), []);
  const send = useCallback(async (body, successMessage) => {
    setBusy(true); setError(""); setNotice("");
    try {
      const payload = await fetch("/api/operations/performance-settings", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ scope, expectedRevision: state?.revision, ...body }) }).then((response) => readApiResponse(response));
      if (payload.state) applyState(payload.state); else await load(scope);
      setNotice(successMessage); return true;
    } catch (requestError) { setError(requestError.message); return false; }
    finally { setBusy(false); }
  }, [scope, state?.revision, applyState, load]);
  async function saveDraft() {
    if (!draftReason.trim()) { setError(t("Enter a reason for this draft.", "اكتب سبب تعديل المسودة.")); return; }
    if (await send({ action: "saveDraft", reason: draftReason.trim(), config }, t("Draft saved.", "تم حفظ المسودة."))) setDraftReason("");
  }
  async function publish() {
    if (!publishReason.trim() || !publishDate) { setError(t("Publishing requires an effective date and reason.", "النشر يتطلب تاريخ سريان وسببًا.")); return; }
    if (validation.length) { setError(t("Resolve validation issues before publishing.", "عالج أخطاء التحقق قبل النشر.")); return; }
    const saved = await send({ action: "publish", reason: publishReason.trim(), effectiveFrom: publishDate }, t("Configuration published for new records.", "تم نشر الإعدادات للسجلات الجديدة."));
    if (saved) { setPublishOpen(false); setPublishReason(""); }
  }
  async function resetOverride() {
    if (!resetReason.trim() || !resetDate) { setError(t("Reset requires an effective date and reason.", "إلغاء التخصيص يتطلب تاريخ سريان وسببًا.")); return; }
    const saved = await send({ action: "resetOverride", reason: resetReason.trim(), effectiveFrom: resetDate }, t("Branch override reset to the global configuration.", "تمت إعادة الفرع إلى الإعدادات العامة."));
    if (saved) { setResetOpen(false); setResetReason(""); }
  }
  const changeScope = (nextScope) => { if (!dirty) load(nextScope); };
  const cloneEffective = () => { setEditing(true); const next = normalizeConfig(state?.effective?.value); setConfig(next); setNotice(t("Effective configuration copied into the editor. Save it as a draft when ready.", "تم نسخ الإعدادات السارية إلى المحرر. احفظها كمسودة عند الانتهاء.")); };

  const sectionProps = { pageOwned:embedded, config, update, isArabic, t, branches: state?.branches || [] };
  return <section className={styles.workspace} aria-label={t("Performance and Reports settings", "إعدادات الأداء والتقارير")}>
    {!embedded&&<header className={styles.heading}><div><span>{t("OPERATIONS CONFIGURATION", "إعدادات العمليات")}</span><h2>{t("Performance & Reports", "الأداء والتقارير")}</h2><p>{t("Versioned business rules for reports, scoring, staffing and succession.", "قواعد عمل بإصدارات للتقارير والدرجات والتوظيف والخلافة.")}</p></div><div className={styles.statusBadges}><b>{state?.effective?.source || t("Loading", "جارٍ التحميل")}</b>{state?.effective?.version != null && <span>v{state.effective.version}</span>}</div></header>}

    <section className="ui-version-lifecycle" aria-label={t("Configuration lifecycle", "مراحل إعدادات الأداء")}><div><b>{editing ? (dirty || !state?.draft ? t("Editing draft", "تعديل المسودة") : t("Saved draft · review before publishing", "مسودة محفوظة · راجع قبل النشر")) : t("Effective version · read only", "الإصدار الساري · للقراءة فقط")}</b><span>V{state?.draft?.version || state?.effective?.version || "—"} · {scope} · {state?.effective?.effectiveFrom || "—"}</span><p>{t("New records use the published version from its effective date. Existing approved records and history retain their original version.", "تستخدم السجلات الجديدة الإصدار المنشور من تاريخ سريانه. تحتفظ السجلات المعتمدة والتاريخ بإصداراتها الأصلية.")}</p></div><PermissionButton permission="settings.configure" type="button" iconOnly={false} disabled={busy || !state} hidden={publishOpen || resetOpen} onClick={!editing ? cloneEffective : unsavedDraft || !state?.draft ? saveDraft : () => setPublishOpen(true)}>{!editing ? t("Create editable draft", "إنشاء مسودة للتعديل") : unsavedDraft || !state?.draft ? t("Save draft", "حفظ المسودة") : t("Review and publish", "مراجعة ونشر")}</PermissionButton></section>
    <EffectivePermissionInfo permission="settings.configure" policy={t("Publishing also follows the configured performance approval policy and second-reviewer rule.","النشر يخضع أيضًا لسياسة اعتماد الأداء وقاعدة المراجع الثاني المعرّفتين.")}/>
    <section className={`panel ${styles.scopeBar}`} aria-label={t("Configuration scope", "نطاق الإعدادات")}>
      <SelectField label={t("Scope", "النطاق")} value={scope} disabled={busy || unsavedDraft} onChange={changeScope} options={[...(globalAccessible ? [["GLOBAL", t("Global default", "الإعداد العام")]] : []), ...(state?.branches || []).map((item) => { const code = branchCode(item); return [code, typeof item === "string" ? item : item.label || item.name || code]; }).filter(([code]) => code)]} />
      <div className={styles.scopeSummary}><span>{scope === "GLOBAL" ? t("Global configuration", "الإعداد العام") : t(`Branch: ${scope}`, `الفرع: ${scope}`)}</span><b>{scope !== "GLOBAL" && state?.inherited ? t("Using global value", "يستخدم القيمة العامة") : t("Own active version", "إصدار مستقل ساري")}</b><small>{state?.effective?.effectiveFrom ? `${t("Effective", "ساري من")} ${state.effective.effectiveFrom}` : t("No publication is active yet", "لا يوجد إصدار منشور ساري")}</small></div>
      {scope !== "GLOBAL" && <ActionButton type="button" className="secondary" disabled={busy || dirty} onClick={() => setResetOpen((value) => !value)}>{t("Reset branch override", "إلغاء تخصيص الفرع")}</ActionButton>}
    </section>
    {unsavedDraft && <p className="alert warning" role="status">{t("Unsaved editor changes. Save or cancel before changing scope.", "توجد تغييرات غير محفوظة. احفظ أو ألغِ قبل تغيير النطاق.")}</p>}
    <OperationalError error={error}/>{notice && <div className="alert success" role="status">{notice}</div>}



    <fieldset disabled={!editing || busy || !canConfigure} className={`panel ${styles.editor} ${!editing || !canConfigure ? "ui-readonly-version" : ""}`} data-readonly={!editing || !canConfigure}>
      {!embedded&&<div className={styles.tabs} role="tablist" aria-label={t("Performance and Reports sections", "أقسام الأداء والتقارير")}>
        {SECTIONS.map(([key, en, ar], index) => <ActionButton key={key} id={`${tabId}-${key}-tab`} type="button" role="tab" aria-selected={activeSection === key} aria-controls={`${tabId}-${key}-panel`} tabIndex={activeSection === key ? 0 : -1} onClick={() => setActiveSection(key)} onKeyDown={(event) => {
          const current = SECTIONS.findIndex(([item]) => item === key); let next;
          if (event.key === "Home") next = 0; if (event.key === "End") next = SECTIONS.length - 1;
          if (["ArrowLeft", "ArrowRight"].includes(event.key)) next = (current + (event.key === (isArabic ? "ArrowLeft" : "ArrowRight") ? 1 : -1) + SECTIONS.length) % SECTIONS.length;
          if (next !== undefined) { event.preventDefault(); setActiveSection(SECTIONS[next][0]); document.getElementById(`${tabId}-${SECTIONS[next][0]}-tab`)?.focus(); }
        }}><span>{String(index + 1).padStart(2, "0")}</span>{isArabic ? ar : en}</ActionButton>)}
      </div>}
      <SettingsSectionIndex><div id={`${tabId}-${activeSection}-panel`} role={embedded?"region":"tabpanel"} aria-label={embedded?SECTIONS.find(row=>row[0]===activeSection)?.[isArabic?2:1]:undefined} aria-labelledby={embedded?undefined:`${tabId}-${activeSection}-tab`} className={styles.panelStack}>
        {activeSection === "reports" && <ReportSettings {...sectionProps} />}
        {activeSection === "processes" && <ProcessTemplates {...sectionProps} />}
        {activeSection === "surveys" && <SurveyTemplates {...sectionProps} />}
        {activeSection === "rewards" && <RewardsEvaluation {...sectionProps} />}
        {activeSection === "appraisal" && <MonthlyAppraisal {...sectionProps} />}
        {activeSection === "suitability" && <SuitabilitySettings {...sectionProps} />}
        {activeSection === "leadership" && <LeadershipStaffing {...sectionProps} />}
        {activeSection === "succession" && <SuccessionSettings {...sectionProps} />}
        {activeSection === "permissions" && <PermissionSettings {...sectionProps} />}
      </div></SettingsSectionIndex>
    </fieldset>

    <section className={`panel ${styles.saveArea}`} hidden={(!editing || !canConfigure) && !resetOpen}>
      <TextAreaField label={t("Draft reason", "سبب المسودة")} value={draftReason} onChange={setDraftReason} placeholder={t("Describe what changed and why", "اشرح ما تغير وسببه")} />
      <div className={styles.actionButtons}><ActionButton type="button" className="secondary" disabled={busy || !unsavedDraft} onClick={() => { setDraftReason(""); setEditing(Boolean(state?.draft)); setConfig(structuredClone(baseline)); setError(""); setNotice(t("Unsaved changes cancelled.", "تم إلغاء التغييرات غير المحفوظة.")); }}>{t("Cancel changes", "إلغاء التغييرات")}</ActionButton></div>
      {publishOpen && <ActionPanel title={t("Publish a new effective version", "نشر إصدار ساري جديد")} reason={publishReason} setReason={setPublishReason} effectiveFrom={publishDate} setEffectiveFrom={setPublishDate} draft={state?.draft} requiresSecondReviewer={config.permissions.requireSecondReviewerForLinkedPublisher} busy={busy} confirm={publish} cancel={() => setPublishOpen(false)} confirmLabel={t("Publish for new records", "نشر للسجلات الجديدة")} t={t} />}
      {resetOpen && <ActionPanel title={t("Reset branch to global", "إعادة الفرع للإعداد العام")} reason={resetReason} setReason={setResetReason} effectiveFrom={resetDate} setEffectiveFrom={setResetDate} busy={busy} confirm={resetOverride} cancel={() => setResetOpen(false)} confirmLabel={t("Reset override", "إلغاء التخصيص")} t={t} danger />}
    </section>
    <ExpandablePreview collapsed label={t("Configuration preview", "معاينة الإعدادات")} isArabic={isArabic}><ConfigurationPreview config={config} scope={scope} state={state} validation={validation} t={t} /></ExpandablePreview>
    <HistoryPanel state={state} t={t} />
  </section>;
}

function TextField({ label, value = "", onChange, type = "text", disabled = false, placeholder = "", min, max, step }) {
  const id = useId();
  return <label className={styles.field} htmlFor={id}><span>{label}</span><input id={id} type={type} value={value ?? ""} disabled={disabled} placeholder={placeholder} min={min} max={max} step={step} onChange={(event) => onChange(event.target.value)} /></label>;
}

function NumberField({ label, value = 0, onChange, min, max, step = 1, disabled = false }) {
  return <TextField label={label} type="number" value={value ?? ""} min={min} max={max} step={step} disabled={disabled} onChange={(value) => onChange(value === "" ? null : Number(value))} />;
}

function TextAreaField({ label, value = "", onChange, placeholder = "", disabled = false }) {
  const id = useId();
  return <label className={`${styles.field} ${styles.wideField}`} htmlFor={id}><span>{label}</span><textarea id={id} value={value ?? ""} placeholder={placeholder} disabled={disabled} rows={3} onChange={(event) => onChange(event.target.value)} /></label>;
}

function SelectField({ label, value = "", onChange, options = [], disabled = false }) {
  const id = useId();
  return <label className={styles.field} htmlFor={id}><span>{label}</span><select id={id} aria-label={label} value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value)}>{options.map(([optionValue, optionLabel]) => <option key={optionValue} value={optionValue}>{optionLabel}</option>)}</select></label>;
}

function Toggle({ label, checked, onChange, disabled = false, hint }) {
  return <label className={styles.toggle}><input type="checkbox" checked={Boolean(checked)} disabled={disabled} onChange={(event) => onChange(event.target.checked)} /><span>{label}{hint && <small>{hint}</small>}</span></label>;
}

function RolePicker({ label, value, onChange, t }) {
  const selected = list(value);
  return <fieldset className={styles.choiceField}><legend>{label}</legend><div>{ROLES.map((role) => <Toggle key={role} label={role === "ADMIN" ? t("Administrator", "المسؤول") : t("Manager", "المدير")} checked={selected.includes(role)} onChange={(checked) => onChange(checked ? [...selected, role] : selected.filter((item) => item !== role))} />)}</div></fieldset>;
}

function BranchPicker({ label, value, onChange, branches, t }) {
  const selected = list(value);
  const choices = [["*", t("All branches", "كل الفروع")], ...branches.map((item) => [branchCode(item), typeof item === "string" ? item : item.label || item.name || branchCode(item)]).filter(([code]) => code && code !== "*")];
  if (!choices.length) return <StringListField label={label} value={selected} onChange={onChange} addLabel={t("Add branch code", "إضافة رمز فرع")} t={t} />;
  return <fieldset className={styles.choiceField}><legend>{label}</legend><div>{choices.map(([code, name]) => <Toggle key={code} label={name} checked={selected.includes(code)} onChange={(checked) => onChange(checked ? (code === "*" ? ["*"] : [...selected.filter((item) => item !== "*"), code]) : selected.filter((item) => item !== code))} />)}</div></fieldset>;
}

function StringListField({ label, value, onChange, addLabel, t }) {
  const [draft, setDraft] = useState("");
  const values = list(value);
  const add = () => { const next = draft.trim(); if (next && !values.includes(next)) onChange([...values, next]); setDraft(""); };
  return <fieldset className={`${styles.stringList} ${styles.wideField}`}><legend>{label}</legend>{values.length ? <ol>{values.map((item, index) => <li key={`${item}-${index}`}><input aria-label={`${label} ${index + 1}`} value={item} onChange={(event) => onChange(values.map((entry, itemIndex) => itemIndex === index ? event.target.value : entry))} /><ActionButton type="button" className={styles.iconButton} disabled={index === 0} aria-label={t("Move up", "نقل لأعلى")} onClick={() => onChange(moveItem(values, index, -1))}>↑</ActionButton><ActionButton type="button" className={styles.iconButton} disabled={index === values.length - 1} aria-label={t("Move down", "نقل لأسفل")} onClick={() => onChange(moveItem(values, index, 1))}>↓</ActionButton><ActionButton type="button" className={styles.iconButton} aria-label={t("Remove", "حذف")} onClick={() => onChange(values.filter((_, itemIndex) => itemIndex !== index))}>×</ActionButton></li>)}</ol> : <p className={styles.empty}>{t("No entries", "لا توجد عناصر")}</p>}<div className={styles.inlineAdd}><input value={draft} placeholder={addLabel} aria-label={addLabel} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); add(); } }} /><ActionButton type="button" className="secondary" onClick={add} disabled={!draft.trim()}>{t("Add", "إضافة")}</ActionButton></div></fieldset>;
}

function ItemActions({ active, onActive, onUp, onDown, disableUp, disableDown, onClone, t }) {
  return <div className={styles.itemActions}><ActionButton type="button" className={styles.iconButton} onClick={onUp} disabled={disableUp} aria-label={t("Move up", "نقل لأعلى")}>↑</ActionButton><ActionButton type="button" className={styles.iconButton} onClick={onDown} disabled={disableDown} aria-label={t("Move down", "نقل لأسفل")}>↓</ActionButton>{onClone && <ActionButton type="button" className="secondary" onClick={onClone}>{t("Clone version", "نسخ إصدار")}</ActionButton>}<ActionButton type="button" className="secondary" onClick={() => onActive(!active)}>{active ? t("Deactivate", "تعطيل") : t("Reactivate", "إعادة تفعيل")}</ActionButton></div>;
}

function SectionIntro({ title, text, action, pageOwned=false }) {
  if(pageOwned)return action?<div className="ui-page-actions">{action}</div>:null;
  return <div className={styles.sectionIntro}><div><h3>{title}</h3>{text && <p>{text}</p>}</div>{action}</div>;
}

function ConfigurationPreview({ config, scope, state, validation, t }) {
  const activeReports = REPORT_TYPES.filter((type) => config.reports[type]?.active).length;
  const activeProcesses = config.processTemplates.filter((item) => item.active).length;
  const activeSurveys = config.surveyTemplates.filter((item) => item.active).length;
  const incompleteSurveys = config.surveyTemplates.filter((item) => ["TRIP", "BIRTHDAY"].includes(item.reportType) && (!item.active || !item.questions?.length));
  return <section className={`panel ${styles.preview}`} aria-label={t("Configuration preview", "معاينة الإعدادات")}>
    <SectionIntro title={t("Effective configuration preview", "معاينة الإعدادات السارية")} text={t("Read-only summary of the version currently in the editor. Publishing applies it only to new records from the effective date.", "ملخص للقراءة فقط للإصدار الموجود في المحرر. يطبق النشر الإعدادات على السجلات الجديدة من تاريخ السريان.")} />
    <div className={styles.previewMeta}><span><b>{t("Scope", "النطاق")}</b>{scope === "GLOBAL" ? t("Global", "عام") : scope}</span><span><b>{t("Source", "المصدر")}</b>{state?.effective?.source || "—"}</span><span><b>{t("Version", "الإصدار")}</b>{state?.effective?.version ?? "—"}</span><span><b>{t("Draft", "المسودة")}</b>{state?.draft ? t(`Revision ${state.draft.revision}`, `المراجعة ${state.draft.revision}`) : t("None", "لا توجد")}</span></div>
    <div className={styles.previewCards}><article><strong>{activeReports}/3</strong><span>{t("active report types", "أنواع تقارير مفعلة")}</span></article><article><strong>{activeProcesses}</strong><span>{t("active process templates", "قوالب إجراءات مفعلة")}</span></article><article><strong>{activeSurveys}</strong><span>{t("active survey templates", "قوالب استبيان مفعلة")}</span></article><article><strong>{config.evaluation.criteria.filter((item) => item.active !== false).length}</strong><span>{t("active evaluation criteria", "معايير تقييم مفعلة")}</span></article><article><strong>{config.suitability.filter((item) => item.active).length}/4</strong><span>{t("active suitability profiles", "ملفات ملاءمة مفعلة")}</span></article><article><strong>{config.succession.paths.filter((item) => item.enabled).length}</strong><span>{t("enabled succession paths", "مسارات خلافة مفعلة")}</span></article></div>
    {incompleteSurveys.length > 0 && <p className={styles.previewNote}>{t("TRIP and Birthday survey templates remain inactive until their approved question sets are entered here.", "تظل قوالب استبيان الرحلات وأعياد الميلاد معطلة حتى إدخال الأسئلة المعتمدة هنا.")}</p>}
    {validation.length > 0 && <div className={styles.validation} role="status"><b>{t("Resolve before publishing", "يلزم الحل قبل النشر")}</b><ul>{validation.map((message) => <li key={message}>{message}</li>)}</ul></div>}
  </section>;
}

function ReportSettings({ pageOwned, config, update, branches, t }) {
  return <><SectionIntro pageOwned={pageOwned} title={t("Report settings", "إعدادات التقارير")} text={t("Set requirements, approval, evidence and locking independently for each operational report.", "حدد المتطلبات والاعتماد والأدلة والقفل لكل تقرير تشغيلي.")} />{REPORT_TYPES.map((type) => {
    const path = ["reports", type]; const report = config.reports[type];
    const set = (key, value) => update([...path, ...key], value);
    return <article className={styles.configCard} key={type}><div className={styles.cardTitle}><div><span>{type}</span><h4>{type === "TRIP" ? t("Trip report", "تقرير الرحلة") : type === "BIRTHDAY" ? t("Birthday report", "تقرير عيد الميلاد") : t("Shift leadership report", "تقرير قيادة الشيفت")}</h4></div><Toggle label={t("Active", "مفعل")} checked={report.active} onChange={(value) => set(["active"], value)} /></div><div className={styles.fieldGrid}>
      <Toggle label={t("Required", "إلزامي")} checked={report.required} onChange={(value) => set(["required"], value)} />
      <NumberField label={t("Completion deadline after event end (minutes)", "مهلة الإكمال بعد نهاية الحدث (دقائق)")} value={report.completionDeadlineMinutes} min={0} onChange={(value) => set(["completionDeadlineMinutes"], value)} />
      <SelectField label={t("Approval role", "دور الاعتماد")} value={report.approvalRole} onChange={(value) => set(["approvalRole"], value)} options={ROLES.map((role) => [role, role])} />
      <Toggle label={t("Fast “everything planned” action", "إجراء سريع: كل شيء مخطط")} checked={report.fastEverythingPlannedEnabled} onChange={(value) => set(["fastEverythingPlannedEnabled"], value)} />
      <Toggle label={t("Survey required", "الاستبيان إلزامي")} checked={report.surveyRequired} onChange={(value) => set(["surveyRequired"], value)} />
      <Toggle label={t("Unresolved issues block approval", "المشكلات غير المحلولة تمنع الاعتماد")} checked={report.unresolvedIssuesBlockApproval} onChange={(value) => set(["unresolvedIssuesBlockApproval"], value)} />
      <BranchPicker label={t("Enabled branches", "الفروع المفعلة")} value={report.branches} onChange={(value) => set(["branches"], value)} branches={branches} t={t} />
      <StringListField label={t("Required field codes", "رموز الحقول الإلزامية")} value={report.requiredFields} onChange={(value) => set(["requiredFields"], value)} addLabel={t("Field code", "رمز الحقل")} t={t} />
    </div><div className={styles.subsection}><h5>{t("Attachments", "المرفقات")}</h5><div className={styles.fieldGrid}><Toggle label={t("Attachments required", "المرفقات إلزامية")} checked={report.attachments.required} onChange={(value) => set(["attachments", "required"], value)} /><NumberField label={t("Minimum count", "الحد الأدنى للعدد")} value={report.attachments.minimumCount} min={0} onChange={(value) => set(["attachments", "minimumCount"], value)} /><StringListField label={t("Allowed file types", "أنواع الملفات المسموحة")} value={report.attachments.allowedTypes} onChange={(value) => set(["attachments", "allowedTypes"], value)} addLabel="image/jpeg" t={t} /></div></div>
    <div className={styles.subsection}><h5>{t("Reopen and locking", "إعادة الفتح والقفل")}</h5><div className={styles.fieldGrid}><Toggle label={t("Reopen allowed", "إعادة الفتح مسموحة")} checked={report.reopen.allowed} onChange={(value) => set(["reopen", "allowed"], value)} /><Toggle label={t("Reopen reason required", "سبب إعادة الفتح إلزامي")} checked={report.reopen.reasonRequired} onChange={(value) => set(["reopen", "reasonRequired"], value)} /><RolePicker label={t("Roles that may reopen", "الأدوار المسموح لها بإعادة الفتح")} value={report.reopen.roles} onChange={(value) => set(["reopen", "roles"], value)} t={t} /><Toggle label={t("Lock on approval", "القفل عند الاعتماد")} checked={report.locking.lockOnApproval} onChange={(value) => set(["locking", "lockOnApproval"], value)} /><Toggle label={t("Manual lock allowed", "القفل اليدوي مسموح")} checked={report.locking.manualLockAllowed} onChange={(value) => set(["locking", "manualLockAllowed"], value)} /><RolePicker label={t("Roles that may lock", "الأدوار المسموح لها بالقفل")} value={report.locking.roles} onChange={(value) => set(["locking", "roles"], value)} t={t} /></div></div></article>;
  })}</>;
}

function ProcessTemplates({ pageOwned, config, update, branches, t }) {
  const templates = config.processTemplates;
  const setTemplates = (next) => update(["processTemplates"], next);
  const addTemplate = () => setTemplates([...templates, { code: itemCode("PROCESS"), reportType: "TRIP", version: 1, active: false, label: "", labelAr: "", instructions: "", instructionsAr: "", branches: [], effectiveFrom: today(), effectiveTo: null, steps: [] }]);
  return <><SectionIntro pageOwned={pageOwned} title={t("Process templates", "قوالب الإجراءات")} text={t("Versioned bilingual procedures keep historical reports tied to the process used at the time.", "إجراءات ثنائية اللغة بإصدارات تحفظ ارتباط التقارير التاريخية بالإجراء المستخدم وقتها.")} action={<ActionButton type="button" onClick={addTemplate}>{t("Add process template", "إضافة قالب إجراء")}</ActionButton>} />
    {!templates.length && <p className={styles.emptyState}>{t("No process templates yet.", "لا توجد قوالب إجراءات بعد.")}</p>}
    {templates.map((template, index) => {
      const replace = (next) => setTemplates(templates.map((item, itemIndex) => itemIndex === index ? next : item));
      const set = (key, value) => replace({ ...template, [key]: value });
      const clone = () => setTemplates([...templates, { ...structuredClone(template), code: itemCode(template.code || "PROCESS"), version: Number(template.version || 0) + 1, active: false, effectiveFrom: today(), effectiveTo: null }]);
      return <article className={`${styles.configCard} ${template.active ? "" : styles.inactive}`} key={`${template.code}-${index}`}><div className={styles.cardTitle}><div><span>{template.reportType} · v{template.version}</span><h4>{template.label || template.code}</h4></div><ItemActions active={template.active} onActive={(active) => set("active", active)} onUp={() => setTemplates(moveItem(templates, index, -1))} onDown={() => setTemplates(moveItem(templates, index, 1))} disableUp={index === 0} disableDown={index === templates.length - 1} onClone={clone} t={t} /></div>
        <div className={styles.fieldGrid}><TextField label={t("Template code", "رمز القالب")} value={template.code} onChange={(value) => set("code", value)} /><SelectField label={t("Report type", "نوع التقرير")} value={template.reportType} onChange={(value) => set("reportType", value)} options={REPORT_TYPES.map((type) => [type, type])} /><NumberField label={t("Version", "الإصدار")} value={template.version} min={1} onChange={(value) => set("version", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={template.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={template.labelAr} onChange={(value) => set("labelAr", value)} /><TextField label={t("Effective from", "ساري من")} type="date" value={template.effectiveFrom} onChange={(value) => set("effectiveFrom", value)} /><TextField label={t("Effective to", "ساري حتى")} type="date" value={template.effectiveTo} onChange={(value) => set("effectiveTo", value || null)} /><TextAreaField label={t("English instructions", "التعليمات بالإنجليزية")} value={template.instructions} onChange={(value) => set("instructions", value)} /><TextAreaField label={t("Arabic instructions", "التعليمات بالعربية")} value={template.instructionsAr} onChange={(value) => set("instructionsAr", value)} /><BranchPicker label={t("Branches", "الفروع")} value={template.branches} onChange={(value) => set("branches", value)} branches={branches} t={t} /></div>
        {['TRIP','BIRTHDAY'].includes(template.reportType)&&<div><p>{t('Add the requested operational steps to this draft. Review requirements and publish explicitly; existing reports keep their snapshots.','أضف خطوات التشغيل المطلوبة إلى هذه المسودة، ثم راجع المتطلبات وانشر صراحة. تحتفظ التقارير الحالية بنسخها.')}</p><ActionButton type="button" iconOnly={false} className="secondary" onClick={()=>{const steps=appendProcessSuggestions(template.reportType,template.steps||[]);if(steps.length!==(template.steps||[]).length)replace({...template,steps,version:Number(template.version||0)+1});}}>{t('Add suggested operational steps','إضافة خطوات التشغيل المقترحة')}</ActionButton></div>}
        <ProcessSteps steps={template.steps || []} onChange={(steps) => set("steps", steps)} branches={branches} t={t} />
      </article>;
    })}</>;
}

function ProcessSteps({ steps, onChange, branches, t }) {
  const add = () => onChange([...steps, { code: itemCode("STEP"), order: (steps.length + 1) * 10, active: true, label: "", labelAr: "", instructions: "", instructionsAr: "", required: false, responsibleEmployeeRequired: false, evidenceRequired: false, branches: [] }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Steps", "الخطوات")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add step", "إضافة خطوة")}</ActionButton>} />{!steps.length && <p className={styles.empty}>{t("No steps", "لا توجد خطوات")}</p>}{steps.map((step, index) => {
    const replace = (next) => onChange(steps.map((item, itemIndex) => itemIndex === index ? next : item)); const set = (key, value) => replace({ ...step, [key]: value });
    return <article className={styles.nestedCard} key={`${step.code}-${index}`}><div className={styles.cardTitle}><div><span>#{step.order}</span><h5>{step.label || step.code}</h5></div><ItemActions active={step.active !== false} onActive={(active) => set("active", active)} onUp={() => onChange(moveItem(steps, index, -1, "order"))} onDown={() => onChange(moveItem(steps, index, 1, "order"))} disableUp={index === 0} disableDown={index === steps.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Step code", "رمز الخطوة")} value={step.code} onChange={(value) => set("code", value)} /><NumberField label={t("Order", "الترتيب")} value={step.order} min={0} onChange={(value) => set("order", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={step.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={step.labelAr} onChange={(value) => set("labelAr", value)} /><TextAreaField label={t("English instructions", "التعليمات بالإنجليزية")} value={step.instructions} onChange={(value) => set("instructions", value)} /><TextAreaField label={t("Arabic instructions", "التعليمات بالعربية")} value={step.instructionsAr} onChange={(value) => set("instructionsAr", value)} /><Toggle label={t("Required", "إلزامية")} checked={step.required} onChange={(value) => set("required", value)} /><Toggle label={t("Responsible employee required", "تحديد الموظف المسؤول إلزامي")} checked={step.responsibleEmployeeRequired} onChange={(value) => set("responsibleEmployeeRequired", value)} /><Toggle label={t("Evidence required", "الدليل إلزامي")} checked={step.evidenceRequired} onChange={(value) => set("evidenceRequired", value)} /><BranchPicker label={t("Branches", "الفروع")} value={step.branches} onChange={(value) => set("branches", value)} branches={branches} t={t} /></div></article>;
  })}</section>;
}

function SurveyTemplates({ pageOwned, config, update, branches, t }) {
  const REPORT_TYPES = ["TRIP", "BIRTHDAY"];
  const templates = config.surveyTemplates; const setTemplates = (next) => update(["surveyTemplates"], next);
  const addTemplate = () => setTemplates([...templates, { code: itemCode("SURVEY"), reportType: "TRIP", version: 1, active: false, label: "", labelAr: "", paperImageRequired: false, branches: [], effectiveFrom: today(), effectiveTo: null, questions: [] }]);
  return <><SectionIntro pageOwned={pageOwned} title={t("Survey templates", "قوالب الاستبيان")} text={t("Eight editable bilingual questions are provided for each report type. Review wording and choices before publishing.", "تتوفر ثمانية أسئلة قابلة للتعديل باللغتين لكل نوع تقرير. راجع الصياغة والاختيارات قبل النشر.")} action={<ActionButton type="button" onClick={addTemplate}>{t("Add survey template", "إضافة قالب استبيان")}</ActionButton>} />
    {!templates.length && <p className={styles.emptyState}>{t("No survey templates yet. Add the approved questions before activating a template.", "لا توجد قوالب استبيان بعد. أضف الأسئلة المعتمدة قبل تفعيل القالب.")}</p>}
    {templates.map((template, index) => { const replace = (next) => setTemplates(templates.map((item, itemIndex) => itemIndex === index ? next : item)); const set = (key, value) => replace({ ...template, [key]: value }); const clone = () => setTemplates([...templates, { ...structuredClone(template), code: itemCode(template.code || "SURVEY"), version: Number(template.version || 0) + 1, active: false, effectiveFrom: today(), effectiveTo: null }]); return <article className={`${styles.configCard} ${template.active ? "" : styles.inactive}`} key={`${template.code}-${index}`}><div className={styles.cardTitle}><div><span>{template.reportType} · v{template.version}</span><h4>{template.label || template.code}</h4></div><ItemActions active={template.active} onActive={(active) => set("active", active)} onUp={() => setTemplates(moveItem(templates, index, -1))} onDown={() => setTemplates(moveItem(templates, index, 1))} disableUp={index === 0} disableDown={index === templates.length - 1} onClone={clone} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Template code", "رمز القالب")} value={template.code} onChange={(value) => set("code", value)} /><SelectField label={t("Report type", "نوع التقرير")} value={template.reportType} onChange={(value) => set("reportType", value)} options={REPORT_TYPES.map((type) => [type, type])} /><NumberField label={t("Version", "الإصدار")} value={template.version} min={1} onChange={(value) => set("version", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={template.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={template.labelAr} onChange={(value) => set("labelAr", value)} /><TextField label={t("Effective from", "ساري من")} type="date" value={template.effectiveFrom} onChange={(value) => set("effectiveFrom", value)} /><TextField label={t("Effective to", "ساري حتى")} type="date" value={template.effectiveTo} onChange={(value) => set("effectiveTo", value || null)} /><Toggle label={t("Paper survey image required", "صورة الاستبيان الورقي إلزامية")} checked={template.paperImageRequired} onChange={(value) => set("paperImageRequired", value)} /><BranchPicker label={t("Branches", "الفروع")} value={template.branches} onChange={(value) => set("branches", value)} branches={branches} t={t} /></div><ActionButton type="button" className="secondary" onClick={()=>replace({...template,questions:surveyQuestions(template.reportType)})}>{t("Load suggested eight questions", "تحميل الأسئلة الثمانية المقترحة")}</ActionButton><SurveyQuestions questions={template.questions || []} onChange={(questions) => set("questions", questions)} t={t} /></article>; })}</>;
}

function SurveyQuestions({ questions, onChange, t }) {
  const add = () => onChange([...questions, { code: itemCode("QUESTION"), order: (questions.length + 1) * 10, active: true, required: true, text: "", textAr: "", choices: [] }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Questions", "الأسئلة")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add question", "إضافة سؤال")}</ActionButton>} />{!questions.length && <p className={styles.empty}>{t("No questions entered", "لم تُدخل أسئلة")}</p>}{questions.map((question, index) => { const replace = (next) => onChange(questions.map((item, itemIndex) => itemIndex === index ? next : item)); const set = (key, value) => replace({ ...question, [key]: value }); return <article className={styles.nestedCard} key={`${question.code}-${index}`}><div className={styles.cardTitle}><div><span>#{question.order}</span><h5>{question.text || question.code}</h5></div><ItemActions active={question.active !== false} onActive={(active) => set("active", active)} onUp={() => onChange(moveItem(questions, index, -1, "order"))} onDown={() => onChange(moveItem(questions, index, 1, "order"))} disableUp={index === 0} disableDown={index === questions.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Question code", "رمز السؤال")} value={question.code} onChange={(value) => set("code", value)} /><NumberField label={t("Order", "الترتيب")} value={question.order} min={0} onChange={(value) => set("order", value)} /><TextAreaField label={t("English question", "السؤال بالإنجليزية")} value={question.text} onChange={(value) => set("text", value)} /><TextAreaField label={t("Arabic question", "السؤال بالعربية")} value={question.textAr} onChange={(value) => set("textAr", value)} /><Toggle label={t("Answer required", "الإجابة إلزامية")} checked={question.required} onChange={(value) => set("required", value)} /></div><SurveyChoices choices={question.choices || []} onChange={(choices) => set("choices", choices)} t={t} /></article>; })}</section>;
}

function SurveyChoices({ choices, onChange, t }) {
  const add = () => onChange([...choices, { code: itemCode("CHOICE"), label: "", labelAr: "", numericValue: 0, active: true, commentRequired: false, followUpSuggested: false }]);
  return <section className={styles.choiceList}><div className={styles.listHeading}><h6>{t("Answer choices", "خيارات الإجابة")}</h6><ActionButton type="button" className="secondary" onClick={add}>{t("Add choice", "إضافة خيار")}</ActionButton></div>{choices.map((choice, index) => { const replace = (next) => onChange(choices.map((item, itemIndex) => itemIndex === index ? next : item)); const set = (key, value) => replace({ ...choice, [key]: value }); return <div className={styles.choiceRow} key={`${choice.code}-${index}`}><TextField label={t("Code", "الرمز")} value={choice.code} onChange={(value) => set("code", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={choice.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={choice.labelAr} onChange={(value) => set("labelAr", value)} /><NumberField label={t("Numeric value", "القيمة الرقمية")} value={choice.numericValue} onChange={(value) => set("numericValue", value)} /><Toggle label={t("Active", "مفعل")} checked={choice.active !== false} onChange={(value) => set("active", value)} /><Toggle label={t("Comment required", "التعليق إلزامي")} checked={choice.commentRequired} onChange={(value) => set("commentRequired", value)} /><Toggle label={t("Suggest follow-up", "اقتراح متابعة")} checked={choice.followUpSuggested} onChange={(value) => set("followUpSuggested", value)} /><div className={styles.rowButtons}><ActionButton type="button" className={styles.iconButton} disabled={index === 0} onClick={() => onChange(moveItem(choices, index, -1))}>↑</ActionButton><ActionButton type="button" className={styles.iconButton} disabled={index === choices.length - 1} onClick={() => onChange(moveItem(choices, index, 1))}>↓</ActionButton></div></div>; })}</section>;
}

function RewardsEvaluation({ pageOwned, config, update, t }) {
  const rewards = config.rewards; const setReward = (path, value) => update(["rewards", ...path], value);
  const evaluation = config.evaluation; const setEvaluation = (path, value) => update(["evaluation", ...path], value);
  return <><SectionIntro pageOwned={pageOwned} title={t("Rewards, penalties and evaluation", "المكافآت والجزاءات والتقييم")} text={t("Configure event scoring and the versioned criteria used by daily evaluation.", "اضبط درجات الأحداث والمعايير ذات الإصدارات المستخدمة في التقييم اليومي.")} />
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("EVENT SCORING", "درجات الأحداث")}</span><h4>{t("Rewards and penalties", "المكافآت والجزاءات")}</h4></div><Toggle label={t("Active", "مفعل")} checked={rewards.active} onChange={(value) => setReward(["active"], value)} /></div><div className={styles.fieldGrid}><Toggle label={t("Attendance scoring enabled", "تفعيل درجات الحضور")} checked={rewards.attendanceScoringEnabled} onChange={(value) => setReward(["attendanceScoringEnabled"], value)} /><NumberField label={t("On-time bonus", "مكافأة الحضور في الموعد")} value={rewards.onTimeBonus} onChange={(value) => setReward(["onTimeBonus"], value)} /><NumberField label={t("Absence deduction", "خصم الغياب")} value={rewards.absenceDeduction} onChange={(value) => setReward(["absenceDeduction"], value)} /><NumberField label={t("Maximum positive points / event", "أقصى نقاط إيجابية / حدث")} value={rewards.maximumPositivePointsPerEvent} min={0} onChange={(value) => setReward(["maximumPositivePointsPerEvent"], value)} /><NumberField label={t("Maximum negative points / event", "أقصى نقاط سلبية / حدث")} value={rewards.maximumNegativePointsPerEvent} min={0} onChange={(value) => setReward(["maximumNegativePointsPerEvent"], value)} /><NumberField label={t("Maximum monthly event bonus", "أقصى مكافأة أحداث شهرية")} value={rewards.maximumMonthlyEventBonus} min={0} onChange={(value) => setReward(["maximumMonthlyEventBonus"], value)} /><NumberField label={t("Maximum monthly event penalty", "أقصى جزاء أحداث شهري")} value={rewards.maximumMonthlyEventPenalty} min={0} onChange={(value) => setReward(["maximumMonthlyEventPenalty"], value)} /><Toggle label={t("Attendance may add event impact", "يمكن للحضور إضافة أثر حدث")} checked={rewards.attendanceMayCreateAdditionalEventImpact} onChange={(value) => setReward(["attendanceMayCreateAdditionalEventImpact"], value)} /><Toggle label={t("Use report-type values", "استخدام قيم حسب نوع التقرير")} checked={rewards.useReportTypeValues} onChange={(value) => setReward(["useReportTypeValues"], value)} />{REPORT_TYPES.map((type) => <NumberField key={type} label={`${type} ${t("value", "القيمة")}`} value={rewards.reportTypeValues[type]} onChange={(value) => setReward(["reportTypeValues", type], value)} />)}<Toggle label={t("Team-leader multiplier enabled", "تفعيل معامل قائد الفريق")} checked={rewards.teamLeaderValues.enabled} onChange={(value) => setReward(["teamLeaderValues", "enabled"], value)} /><NumberField label={t("Team-leader multiplier", "معامل قائد الفريق")} value={rewards.teamLeaderValues.multiplier} min={0} step={0.1} onChange={(value) => setReward(["teamLeaderValues", "multiplier"], value)} /></div>
      <LatenessBands items={rewards.latenessBands} onChange={(value) => setReward(["latenessBands"], value)} t={t} />
      <PerformanceLevels items={rewards.performanceLevels} onChange={(value) => setReward(["performanceLevels"], value)} t={t} />
      <div className={styles.subsection}><h5>{t("Event workflow roles", "أدوار سير عمل الأحداث")}</h5><div className={styles.fieldGrid}>{[["propose", t("May propose", "يمكنه الاقتراح")], ["approve", t("May approve", "يمكنه الاعتماد")], ["reject", t("May reject", "يمكنه الرفض")], ["reopen", t("May reopen", "يمكنه إعادة الفتح")]].map(([key, label]) => <RolePicker key={key} label={label} value={rewards.roles[key]} onChange={(value) => setReward(["roles", key], value)} t={t} />)}</div></div>
    </article>
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("DAILY EVALUATION", "التقييم اليومي")}</span><h4>{t("Rules and criteria", "القواعد والمعايير")}</h4></div><span className={styles.versionChip}>{evaluation.criteriaVersionId ? `${t("Published", "منشور")} ${evaluation.criteriaVersionId}` : t("New criteria version", "إصدار معايير جديد")}</span></div><div className={styles.fieldGrid}><SelectField label={t("Unreviewed score mode", "وضع درجة غير المراجع")} value={evaluation.rules.defaultScoreMode} onChange={(value) => setEvaluation(["rules", "defaultScoreMode"], value)} options={[["FULL_UNREVIEWED", t("Full score until reviewed", "الدرجة كاملة حتى المراجعة")], ["ZERO_UNREVIEWED", t("Zero until reviewed", "صفر حتى المراجعة")]]} /><NumberField label={t("Penalty deduction", "خصم الجزاء")} value={evaluation.rules.penaltyDeduction} min={0} onChange={(value) => setEvaluation(["rules", "penaltyDeduction"], value)} /><NumberField label={t("Guidance deduction", "خصم التوجيه")} value={evaluation.rules.guidanceDeduction} min={0} onChange={(value) => setEvaluation(["rules", "guidanceDeduction"], value)} /><Toggle label={t("Reason required for deduction", "سبب الخصم إلزامي")} checked={evaluation.rules.requireReasonForDeduction} onChange={(value) => setEvaluation(["rules", "requireReasonForDeduction"], value)} /><Toggle label={t("Review required before close", "المراجعة إلزامية قبل الإغلاق")} checked={evaluation.rules.requireReviewBeforeClose} onChange={(value) => setEvaluation(["rules", "requireReviewBeforeClose"], value)} /></div><EvaluationCriteria items={evaluation.criteria} onChange={(value) => setEvaluation(["criteria"], value)} t={t} /></article>
  </>;
}

function LatenessBands({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("LATE"), active: true, minimumMinutes: 1, maximumMinutes: 1, points: 0 }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Lateness bands", "شرائح التأخير")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add band", "إضافة شريحة")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.code}-${index}`}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><NumberField label={t("Minimum minutes", "أدنى دقائق")} value={item.minimumMinutes} min={0} onChange={(value) => set("minimumMinutes", value)} /><NumberField label={t("Maximum minutes", "أقصى دقائق")} value={item.maximumMinutes} min={0} onChange={(value) => set("maximumMinutes", value)} /><NumberField label={t("Points", "النقاط")} value={item.points} onChange={(value) => set("points", value)} /><Toggle label={t("Active", "مفعل")} checked={item.active !== false} onChange={(value) => set("active", value)} /><ItemActions active={item.active !== false} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div>; })}</section>;
}

function PerformanceLevels({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("LEVEL"), label: "", labelAr: "", points: 0, active: true, evidenceRequired: false, commentRequired: false, approvalRequired: false }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Performance levels", "مستويات الأداء")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add level", "إضافة مستوى")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <article className={styles.nestedCard} key={`${item.code}-${index}`}><div className={styles.cardTitle}><h5>{item.label || item.code}</h5><ItemActions active={item.active !== false} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={item.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={item.labelAr} onChange={(value) => set("labelAr", value)} /><NumberField label={t("Points", "النقاط")} value={item.points} onChange={(value) => set("points", value)} /><Toggle label={t("Evidence required", "الدليل إلزامي")} checked={item.evidenceRequired} onChange={(value) => set("evidenceRequired", value)} /><Toggle label={t("Comment required", "التعليق إلزامي")} checked={item.commentRequired} onChange={(value) => set("commentRequired", value)} /><Toggle label={t("Approval required", "الاعتماد إلزامي")} checked={item.approvalRequired} onChange={(value) => set("approvalRequired", value)} /></div></article>; })}</section>;
}

function EvaluationCriteria({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("CRITERION"), label: "", labelAr: "", category: "", maxScore: 0, active: true, sortOrder: (items.length + 1) * 10, reasons: [] }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Evaluation criteria", "معايير التقييم")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add criterion", "إضافة معيار")}</ActionButton>} />{items.map((item, index) => { const replace = (next) => onChange(items.map((entry, itemIndex) => itemIndex === index ? next : entry)); const set = (key, value) => replace({ ...item, [key]: value }); return <article className={styles.nestedCard} key={`${item.code}-${index}`}><div className={styles.cardTitle}><div><span>#{item.sortOrder}</span><h5>{item.label || item.code}</h5></div><ItemActions active={item.active !== false} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1, "sortOrder"))} onDown={() => onChange(moveItem(items, index, 1, "sortOrder"))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("Category", "الفئة")} value={item.category} onChange={(value) => set("category", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={item.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={item.labelAr} onChange={(value) => set("labelAr", value)} /><NumberField label={t("Maximum score", "أقصى درجة")} value={item.maxScore} min={0} onChange={(value) => set("maxScore", value)} /><NumberField label={t("Sort order", "الترتيب")} value={item.sortOrder} min={0} onChange={(value) => set("sortOrder", value)} /></div><CriterionReasons items={item.reasons || []} onChange={(value) => set("reasons", value)} t={t} /></article>; })}</section>;
}

function CriterionReasons({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("REASON"), label: "", labelAr: "", active: true, sortOrder: (items.length + 1) * 10 }]);
  return <section className={styles.choiceList}><div className={styles.listHeading}><h6>{t("Deduction reasons", "أسباب الخصم")}</h6><ActionButton type="button" className="secondary" onClick={add}>{t("Add reason", "إضافة سبب")}</ActionButton></div>{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.choiceRow} key={`${item.code}-${index}`}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={item.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={item.labelAr} onChange={(value) => set("labelAr", value)} /><NumberField label={t("Order", "الترتيب")} value={item.sortOrder} min={0} onChange={(value) => set("sortOrder", value)} /><Toggle label={t("Active", "مفعل")} checked={item.active !== false} onChange={(value) => set("active", value)} /><div className={styles.rowButtons}><ActionButton type="button" className={styles.iconButton} disabled={index === 0} onClick={() => onChange(moveItem(items, index, -1, "sortOrder"))}>↑</ActionButton><ActionButton type="button" className={styles.iconButton} disabled={index === items.length - 1} onClick={() => onChange(moveItem(items, index, 1, "sortOrder"))}>↓</ActionButton></div></div>; })}</section>;
}

function MonthlyAppraisal({ pageOwned, config, update, t }) {
  const appraisal = config.monthlyAppraisal; const set = (path, value) => update(["monthlyAppraisal", ...path], value);
  const source = appraisal.sourceFormula || {};
  return <><SectionIntro pageOwned={pageOwned} title={t("Monthly appraisal", "التقييم الشهري")} text={t("Configure aggregation, workflow and formula parameters. Published appraisals retain their immutable formula version.", "اضبط التجميع وسير العمل ومعاملات المعادلة. تحتفظ التقييمات المنشورة بإصدار المعادلة الثابت.")} />
    <article className={styles.configCard}><h4>{t('Daily sources and Employee of the Month eligibility','المصادر اليومية وأهلية موظف الشهر')}</h4><p>{t('Only closed daily evaluations with the selected completed statuses are included. Missing weighted components block final eligibility; their weights are never redistributed automatically.','تُحتسب التقييمات اليومية المغلقة بالحالات المكتملة المختارة فقط. نقص مكونات المعادلة يمنع الأهلية النهائية، ولا تُعاد توزيع أوزانها تلقائيًا.')}</p><div className={styles.fieldGrid}>{['REVIEWED','EXCEPTION','MODIFIED','CLOSED'].map(status=><Toggle key={status} label={t(status.charAt(0)+status.slice(1).toLowerCase(), {REVIEWED:"تمت المراجعة",EXCEPTION:"استثناء",MODIFIED:"معدّل",CLOSED:"مغلق"}[status])} checked={(appraisal.includedEvaluationStatuses||['REVIEWED','EXCEPTION','MODIFIED','CLOSED']).includes(status)} onChange={checked=>set(['includedEvaluationStatuses'],checked?[...(appraisal.includedEvaluationStatuses||['REVIEWED','EXCEPTION','MODIFIED','CLOSED']),status]: (appraisal.includedEvaluationStatuses||['REVIEWED','EXCEPTION','MODIFIED','CLOSED']).filter(s=>s!==status))}/>)}<NumberField label={t('Minimum completed evaluation days','الحد الأدنى لأيام التقييم المكتملة')} value={appraisal.employeeOfMonth?.minimumDailyEvaluations||0} min={0} max={366} onChange={value=>set(['employeeOfMonth'],{minimumDailyEvaluations:0,minimumScore:0,activeEmployeesOnly:false,requireMonthlyApproval:appraisal.workflow.approvalRequired,tieBreakers:['FINAL_SCORE','EMPLOYEE_NAME','EMPLOYEE_ID'],...appraisal.employeeOfMonth,minimumDailyEvaluations:value})}/><NumberField label={t('Minimum candidate score','أدنى درجة للمرشح')} value={appraisal.employeeOfMonth?.minimumScore||0} onChange={value=>set(['employeeOfMonth'],{minimumDailyEvaluations:0,minimumScore:0,activeEmployeesOnly:false,requireMonthlyApproval:appraisal.workflow.approvalRequired,tieBreakers:['FINAL_SCORE','EMPLOYEE_NAME','EMPLOYEE_ID'],...appraisal.employeeOfMonth,minimumScore:value})}/><Toggle label={t('Active employees only','الموظفون النشطون فقط')} checked={appraisal.employeeOfMonth?.activeEmployeesOnly||false} onChange={value=>set(['employeeOfMonth'],{minimumDailyEvaluations:0,minimumScore:0,activeEmployeesOnly:false,requireMonthlyApproval:appraisal.workflow.approvalRequired,tieBreakers:['FINAL_SCORE','EMPLOYEE_NAME','EMPLOYEE_ID'],...appraisal.employeeOfMonth,activeEmployeesOnly:value})}/><Toggle label={t('Monthly approval required for selection','اعتماد التقييم الشهري مطلوب للاختيار')} checked={appraisal.employeeOfMonth?.requireMonthlyApproval??appraisal.workflow.approvalRequired} onChange={value=>set(['employeeOfMonth'],{minimumDailyEvaluations:0,minimumScore:0,activeEmployeesOnly:false,requireMonthlyApproval:appraisal.workflow.approvalRequired,tieBreakers:['FINAL_SCORE','EMPLOYEE_NAME','EMPLOYEE_ID'],...appraisal.employeeOfMonth,requireMonthlyApproval:value})}/><SelectField label={t('Tie-breaking order after score','ترتيب كسر التعادل بعد الدرجة')} value={(appraisal.employeeOfMonth?.tieBreakers||['FINAL_SCORE','EMPLOYEE_NAME','EMPLOYEE_ID']).join(',')} onChange={value=>set(['employeeOfMonth'],{minimumDailyEvaluations:0,minimumScore:0,activeEmployeesOnly:false,requireMonthlyApproval:appraisal.workflow.approvalRequired,...appraisal.employeeOfMonth,tieBreakers:value.split(',')})} options={[["FINAL_SCORE,EMPLOYEE_NAME,EMPLOYEE_ID",t('Name, then stable employee ID','الاسم ثم رقم الموظف الثابت')],["FINAL_SCORE,COMPLETED_DAYS,EMPLOYEE_NAME,EMPLOYEE_ID",t('Completed days, then name and ID','الأيام المكتملة ثم الاسم والرقم')],["FINAL_SCORE,ATTENDANCE_SCORE,COMPLETED_DAYS,EMPLOYEE_NAME,EMPLOYEE_ID",t('Attendance, completed days, then name and ID','الحضور ثم الأيام المكتملة ثم الاسم والرقم')]]}/></div></article>
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("MONTHLY SCORE", "الدرجة الشهرية")}</span><h4>{t("Aggregation and limits", "التجميع والحدود")}</h4></div><Toggle label={t("Active", "مفعل")} checked={appraisal.active} onChange={(value) => set(["active"], value)} /></div><div className={styles.fieldGrid}><SelectField label={t("Aggregation method", "طريقة التجميع")} value={appraisal.aggregationMethod} onChange={(value) => set(["aggregationMethod"], value)} options={[["AVERAGE_PERCENTAGE", t("Average percentage", "متوسط النسبة")], ["WEIGHTED_AVERAGE", t("Weighted average", "المتوسط المرجح")], ["SUM", t("Sum", "المجموع")]]} /><SelectField label={t("Event adjustment treatment", "معالجة تعديلات الأحداث")} value={appraisal.eventAdjustmentTreatment} onChange={(value) => set(["eventAdjustmentTreatment"], value)} options={[["ADD_TO_AGGREGATE", t("Add to aggregate", "إضافة إلى التجميع")], ["SEPARATE_COMPONENT", t("Separate component", "مكوّن منفصل")], ["IGNORE", t("Ignore", "تجاهل")]]} /><NumberField label={t("Monthly positive cap", "الحد الإيجابي الشهري")} value={appraisal.monthlyPositiveCap} min={0} onChange={(value) => set(["monthlyPositiveCap"], value)} /><NumberField label={t("Monthly negative cap", "الحد السلبي الشهري")} value={appraisal.monthlyNegativeCap} min={0} onChange={(value) => set(["monthlyNegativeCap"], value)} /><NumberField label={t("Final score minimum", "أدنى درجة نهائية")} value={appraisal.finalScoreMinimum} onChange={(value) => set(["finalScoreMinimum"], value)} /><NumberField label={t("Final score maximum", "أقصى درجة نهائية")} value={appraisal.finalScoreMaximum} onChange={(value) => set(["finalScoreMaximum"], value)} /><SelectField label={t("Minimum coverage unit", "وحدة الحد الأدنى للتغطية")} value={appraisal.minimumDataCoverage.unit} onChange={(value) => set(["minimumDataCoverage", "unit"], value)} options={[["PERCENTAGE", t("Percentage", "نسبة مئوية")], ["DAYS", t("Days", "أيام")]]} /><NumberField label={t("Minimum data coverage", "الحد الأدنى لتغطية البيانات")} value={appraisal.minimumDataCoverage.value} min={0} max={appraisal.minimumDataCoverage.unit === "PERCENTAGE" ? 100 : 366} onChange={(value) => set(["minimumDataCoverage", "value"], value)} /></div><PerformanceBands items={appraisal.performanceBands} onChange={(value) => set(["performanceBands"], value)} t={t} /></article>
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("WORKFLOW", "سير العمل")}</span><h4>{t("Review, approval and recalculation", "المراجعة والاعتماد وإعادة الحساب")}</h4></div></div><div className={styles.fieldGrid}><Toggle label={t("Provisional results allowed", "السماح بالنتائج المؤقتة")} checked={appraisal.workflow.provisionalAllowed} onChange={(value) => set(["workflow", "provisionalAllowed"], value)} /><Toggle label={t("Review required", "المراجعة إلزامية")} checked={appraisal.workflow.reviewRequired} onChange={(value) => set(["workflow", "reviewRequired"], value)} /><Toggle label={t("Approval required", "الاعتماد إلزامي")} checked={appraisal.workflow.approvalRequired} onChange={(value) => set(["workflow", "approvalRequired"], value)} /><Toggle label={t("Lock on approval", "القفل عند الاعتماد")} checked={appraisal.workflow.lockOnApproval} onChange={(value) => set(["workflow", "lockOnApproval"], value)} /><Toggle label={t("Reopen reason required", "سبب إعادة الفتح إلزامي")} checked={appraisal.workflow.reopenReasonRequired} onChange={(value) => set(["workflow", "reopenReasonRequired"], value)} /><RolePicker label={t("Review roles", "أدوار المراجعة")} value={appraisal.workflow.reviewRoles} onChange={(value) => set(["workflow", "reviewRoles"], value)} t={t} /><RolePicker label={t("Approval roles", "أدوار الاعتماد")} value={appraisal.workflow.approvalRoles} onChange={(value) => set(["workflow", "approvalRoles"], value)} t={t} /><RolePicker label={t("Reopen roles", "أدوار إعادة الفتح")} value={appraisal.workflow.reopenRoles} onChange={(value) => set(["workflow", "reopenRoles"], value)} t={t} /><SelectField label={t("When source data changes", "عند تغير بيانات المصدر")} value={appraisal.recalculation.onSourceChange} onChange={(value) => set(["recalculation", "onSourceChange"], value)} options={[["NEVER", t("Never", "أبدًا")], ["DRAFT_ONLY", t("Draft only", "المسودة فقط")], ["ALWAYS_NEW_VERSION", t("Always create new version", "إنشاء إصدار جديد دائمًا")]]} /><SelectField label={t("Approved record behavior", "سلوك السجل المعتمد")} value={appraisal.recalculation.approvedRecordBehavior} onChange={(value) => set(["recalculation", "approvedRecordBehavior"], value)} options={[["PRESERVE", t("Preserve", "احتفاظ")], ["CREATE_NEW_VERSION", t("Create new version", "إنشاء إصدار جديد")]]} /></div></article>
    <SourceNormalization value={appraisal.sourceNormalization} onChange={value=>set(["sourceNormalization"],value)} t={t} />
    <MonthlySourcesSettings value={appraisal.sources} onChange={value=>set(['sources'],value)} t={t} rewards={config.rewards.performanceLevels} surveys={config.surveyTemplates} Field={TextField} NumberField={NumberField} Toggle={Toggle} StringListField={StringListField}/>
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("FORMULA", "المعادلة")}</span><h4>{t("Editable formula parameters", "معاملات المعادلة القابلة للتعديل")}</h4></div><span className={styles.versionChip}>{appraisal.formulaVersionId || t("New formula version", "إصدار معادلة جديد")}</span></div><FormulaParameters value={appraisal.formulaParameters || {}} onChange={(value) => set(["formulaParameters"], value)} t={t} /><div className={styles.provenance}><h5>{t("Source formula (read only)", "معادلة المصدر (للقراءة فقط)")}</h5><dl><div><dt>{t("Code", "الرمز")}</dt><dd>{source.code || "—"}</dd></div><div><dt>{t("Label", "الاسم")}</dt><dd>{source.label || "—"}</dd></div><div><dt>{t("Effective from", "ساري من")}</dt><dd>{source.effectiveFrom || "—"}</dd></div><div><dt>{t("Effective to", "ساري حتى")}</dt><dd>{source.effectiveTo || "—"}</dd></div></dl></div></article>
  </>;
}

function FormulaParameters({ value, onChange, t }) {
  const entries = Object.entries(value || {}); const [keyDraft, setKeyDraft] = useState("");
  const add = () => { const key = keyDraft.trim(); if (key && !(key in value)) onChange({ ...value, [key]: 0 }); setKeyDraft(""); };
  return <section className={styles.parameterEditor}>{entries.map(([key, parameter]) => <div className={styles.parameterRow} key={key}><TextField label={t("Parameter", "المعامل")} value={key} onChange={(nextKey) => { if (!nextKey || nextKey === key || nextKey in value) return; const next = {}; entries.forEach(([entryKey, entryValue]) => { next[entryKey === key ? nextKey : entryKey] = entryValue; }); onChange(next); }} /><NumberField label={t("Value", "القيمة")} value={parameter} step={0.01} onChange={(nextValue) => onChange({ ...value, [key]: nextValue })} /><ActionButton type="button" className={styles.iconButton} aria-label={t("Remove parameter", "حذف المعامل")} onClick={() => onChange(Object.fromEntries(entries.filter(([entryKey]) => entryKey !== key)))}>×</ActionButton></div>)}<div className={styles.inlineAdd}><input value={keyDraft} aria-label={t("New parameter name", "اسم معامل جديد")} placeholder={t("Parameter name", "اسم المعامل")} onChange={(event) => setKeyDraft(event.target.value)} /><ActionButton type="button" className="secondary" onClick={add} disabled={!keyDraft.trim() || keyDraft in value}>{t("Add parameter", "إضافة معامل")}</ActionButton></div></section>;
}

function PerformanceBands({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("BAND"), label: "", active: true, minimum: 0, maximum: 0 }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Performance bands", "شرائح الأداء")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add band", "إضافة شريحة")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.code}-${index}`}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("Label", "الاسم")} value={item.label} onChange={(value) => set("label", value)} /><NumberField label={t("Minimum", "الحد الأدنى")} value={item.minimum} onChange={(value) => set("minimum", value)} /><NumberField label={t("Maximum", "الحد الأقصى")} value={item.maximum} onChange={(value) => set("maximum", value)} /><Toggle label={t("Active", "مفعل")} checked={item.active !== false} onChange={(value) => set("active", value)} /><ItemActions active={item.active !== false} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div>; })}</section>;
}

function SuitabilitySettings({ pageOwned, config, update, t }) {
  return <><SectionIntro pageOwned={pageOwned} title={t("Suitability and recommendations", "الملاءمة والتوصيات")} text={t("The four required profiles use rolling evidence, weighted factors, thresholds and controlled overrides.", "تستخدم الملفات الأربعة المطلوبة أدلة متحركة وعوامل مرجحة وحدودًا وتجاوزات محكومة.")} />{config.suitability.map((profile, index) => { const replace = (next) => update(["suitability"], config.suitability.map((item, itemIndex) => itemIndex === index ? next : item)); const set = (path, value) => replace(withPath(profile, path, value)); const total = Object.values(profile.weights).reduce((sum, value) => sum + Number(value || 0), 0); return <article className={styles.configCard} key={profile.code}><div className={styles.cardTitle}><div><span>{profile.code}</span><h4>{profile.label}</h4></div><Toggle label={t("Active", "مفعل")} checked={profile.active} onChange={(value) => set(["active"], value)} /></div><div className={styles.fieldGrid}><TextField label={t("Display label", "اسم العرض")} value={profile.label} onChange={(value) => set(["label"], value)} /><NumberField label={t("Rolling window (days)", "النافذة المتحركة (أيام)")} value={profile.rollingWindowDays} min={1} onChange={(value) => set(["rollingWindowDays"], value)} /><NumberField label={t("Maximum recent events", "أقصى أحداث حديثة")} value={profile.maximumRecentEvents} min={0} onChange={(value) => set(["maximumRecentEvents"], value)} /><NumberField label={t("Minimum events", "الحد الأدنى للأحداث")} value={profile.minimumEvents} min={0} onChange={(value) => set(["minimumEvents"], value)} /><SelectField label={t("Weighting mode", "وضع الترجيح")} value={profile.weightingMode} onChange={(value) => set(["weightingMode"], value)} options={[["PERCENTAGE", t("Percentage", "نسبة مئوية")], ["POINTS", t("Points", "نقاط")]]} /></div><div className={styles.subsection}><div className={styles.listHeading}><h5>{t("Weights", "الأوزان")}</h5><span className={total === 100 || profile.weightingMode !== "PERCENTAGE" ? styles.validTotal : styles.invalidTotal}>{t("Total", "المجموع")}: {total}{profile.weightingMode === "PERCENTAGE" ? "%" : ""}</span></div><div className={styles.fieldGrid}>{[["punctuality", t("Punctuality", "الالتزام بالمواعيد")], ["performance", t("Performance", "الأداء")], ["guestFeedback", t("Guest feedback", "ملاحظات الضيوف")], ["processReliability", t("Process reliability", "موثوقية الإجراءات")], ["leadershipProblemResolution", t("Leadership and problem resolution", "القيادة وحل المشكلات")]].map(([key, label]) => <NumberField key={key} label={label} value={profile.weights[key]} min={0} onChange={(value) => set(["weights", key], value)} />)}</div></div><SuitabilityThresholds items={profile.thresholds} onChange={(value) => set(["thresholds"], value)} t={t} /><div className={styles.fieldGrid}><StringListField label={t("Caution rules", "قواعد التحذير")} value={profile.cautionRules} onChange={(value) => set(["cautionRules"], value)} addLabel={t("Rule", "قاعدة")} t={t} /><StringListField label={t("Not-recommended rules", "قواعد غير موصى به")} value={profile.notRecommendedRules} onChange={(value) => set(["notRecommendedRules"], value)} addLabel={t("Rule", "قاعدة")} t={t} /><SelectField label={t("Decay mode", "وضع تناقص الأثر")} value={profile.decay.mode} onChange={(value) => set(["decay", "mode"], value)} options={[["NONE", t("None", "لا يوجد")], ["LINEAR", t("Linear", "خطي")], ["EXPONENTIAL", t("Exponential", "أُسي")]]} /><NumberField label={t("Decay half-life (days)", "نصف عمر التناقص (أيام)")} value={profile.decay.halfLifeDays} min={0} onChange={(value) => set(["decay", "halfLifeDays"], value)} /><Toggle label={t("Override allowed", "التجاوز مسموح")} checked={profile.override.allowed} onChange={(value) => set(["override", "allowed"], value)} /><Toggle label={t("Override reason required", "سبب التجاوز إلزامي")} checked={profile.override.reasonRequired} onChange={(value) => set(["override", "reasonRequired"], value)} /><RolePicker label={t("Override roles", "أدوار التجاوز")} value={profile.override.roles} onChange={(value) => set(["override", "roles"], value)} t={t} /><SelectField label={t("Recalculation trigger", "مشغل إعادة الحساب")} value={profile.recalculation.trigger} onChange={(value) => set(["recalculation", "trigger"], value)} options={[["ON_SOURCE_CHANGE", t("On source change", "عند تغير المصدر")], ["SCHEDULED", t("Scheduled", "مجدول")], ["MANUAL", t("Manual", "يدوي")]]} /><SelectField label={t("Recalculation schedule", "جدول إعادة الحساب")} value={profile.recalculation.schedule || ""} onChange={(value) => set(["recalculation", "schedule"], value || null)} options={[["", "—"], ["DAILY",t("Daily","يومي")],["WEEKLY",t("Weekly (Monday)","أسبوعي (الاثنين)")],["MONTHLY",t("Monthly","شهري")]]} /></div><SourceNormalization value={profile.sourceNormalization} onChange={value=>set(["sourceNormalization"],value)} t={t} /></article>; })}</>;
}

function SuitabilityThresholds({ items, onChange, t }) {
  const add = () => onChange([...items, { status: itemCode("STATUS"), minimum: 0, maximum: 0, active: true }]);
  return <section className={styles.nestedList}><SectionIntro title={t("Recommendation thresholds", "حدود التوصيات")} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add threshold", "إضافة حد")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.status}-${index}`}><TextField label={t("Status", "الحالة")} value={item.status} onChange={(value) => set("status", value)} /><NumberField label={t("Minimum", "الحد الأدنى")} value={item.minimum} onChange={(value) => set("minimum", value)} /><NumberField label={t("Maximum", "الحد الأقصى")} value={item.maximum} onChange={(value) => set("maximum", value)} /><Toggle label={t("Active", "مفعل")} checked={item.active !== false} onChange={(value) => set("active", value)} /><ItemActions active={item.active !== false} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div>; })}</section>;
}

function LeadershipStaffing({ pageOwned, config, update, branches, t }) {
  const leadership = config.shiftLeadership; const setLeadership = (path, value) => update(["shiftLeadership", ...path], value);
  const staffing = config.staffing; const setStaffing = (path, value) => update(["staffing", ...path], value);
  return <><SectionIntro pageOwned={pageOwned} title={t("Shift leadership and staffing", "قيادة الشيفت والتوظيف")} text={t("Set required coverage, leadership evidence, conflict checks and controlled staffing overrides.", "حدد التغطية المطلوبة وأدلة القيادة وفحوص التعارض وتجاوزات التوظيف المحكومة.")} />
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("SHIFT COVERAGE", "تغطية الشيفت")}</span><h4>{t("Leadership requirements", "متطلبات القيادة")}</h4></div><Toggle label={t("Active", "مفعل")} checked={leadership.active} onChange={(value) => setLeadership(["active"], value)} /></div><div className={styles.fieldGrid}><BranchPicker label={t("Enabled branches", "الفروع المفعلة")} value={leadership.enabledBranches} onChange={(value) => setLeadership(["enabledBranches"], value)} branches={branches} t={t} /><WeekdayPicker value={leadership.requiredWeekdays} onChange={(value) => setLeadership(["requiredWeekdays"], value)} t={t} /><DateListField label={t("Selected dates", "تواريخ محددة")} value={leadership.selectedDates} onChange={(value) => setLeadership(["selectedDates"], value)} t={t} /><StringListField label={t("Shift codes", "رموز الشيفت")} value={leadership.shiftCodes} onChange={(value) => setLeadership(["shiftCodes"], value)} addLabel={t("Shift code", "رمز الشيفت")} t={t} /><Toggle label={t("Team leader required", "قائد الفريق إلزامي")} checked={leadership.teamLeaderRequired} onChange={(value) => setLeadership(["teamLeaderRequired"], value)} /><NumberField label={t("Primary leader count", "عدد القادة الأساسيين")} value={leadership.primaryLeaderCount} min={0} onChange={(value) => setLeadership(["primaryLeaderCount"], value)} /><Toggle label={t("Deputy allowed", "السماح بالنائب")} checked={leadership.deputyAllowed} onChange={(value) => setLeadership(["deputyAllowed"], value)} /><NumberField label={t("Ready-time offset (minutes)", "فارق وقت الجاهزية (دقائق)")} value={leadership.requiredReadyTimeOffsetMinutes} min={0} onChange={(value) => setLeadership(["requiredReadyTimeOffsetMinutes"], value)} /><Toggle label={t("Create report automatically", "إنشاء التقرير تلقائيًا")} checked={leadership.automaticReportCreation} onChange={(value) => setLeadership(["automaticReportCreation"], value)} /><TextField label={t("Report due time", "موعد التقرير")} type="time" value={leadership.reportDueTime} onChange={(value) => setLeadership(["reportDueTime"], value || null)} /><SelectField label={t("Approval role", "دور الاعتماد")} value={leadership.approvalRole} onChange={(value) => setLeadership(["approvalRole"], value)} options={ROLES.map((role) => [role, role])} /><Toggle label={t("Prevent self-approval", "منع الاعتماد الذاتي")} checked={leadership.preventSelfApproval} onChange={(value) => setLeadership(["preventSelfApproval"], value)} /><Toggle label={t("Assignment counts as succession evidence", "التكليف يعد دليل خلافة")} checked={leadership.assignmentQualifiesAsSuccessionEvidence} onChange={(value) => setLeadership(["assignmentQualifiesAsSuccessionEvidence"], value)} /></div><div className={styles.subsection}><h5>{t("Replacement", "الاستبدال")}</h5><div className={styles.fieldGrid}><Toggle label={t("Replacement allowed", "الاستبدال مسموح")} checked={leadership.replacement.allowed} onChange={(value) => setLeadership(["replacement", "allowed"], value)} /><Toggle label={t("Reason required", "السبب إلزامي")} checked={leadership.replacement.reasonRequired} onChange={(value) => setLeadership(["replacement", "reasonRequired"], value)} /><RolePicker label={t("Replacement roles", "أدوار الاستبدال")} value={leadership.replacement.roles} onChange={(value) => setLeadership(["replacement", "roles"], value)} t={t} /></div></div><DateRanges title={t("Busy periods", "فترات الازدحام")} items={leadership.busyPeriods} onChange={(value) => setLeadership(["busyPeriods"], value)} t={t} /><DateRanges title={t("Holidays", "العطلات")} items={leadership.holidays} onChange={(value) => setLeadership(["holidays"], value)} t={t} /></article>
    <article className={styles.configCard}><div className={styles.cardTitle}><div><span>{t("STAFFING", "التوظيف")}</span><h4>{t("Assignment rules", "قواعد التكليف")}</h4></div><Toggle label={t("Active", "مفعل")} checked={staffing.active} onChange={(value) => setStaffing(["active"], value)} /></div><div className={styles.fieldGrid}><NumberField label={t("Maximum responsible birthday hosts", "أقصى مضيفي عيد ميلاد مسؤولين")} value={staffing.maximumResponsibleBirthdayHosts} min={0} onChange={(value) => setStaffing(["maximumResponsibleBirthdayHosts"], value)} /><NumberField label={t("Primary trip team leaders", "قادة فريق الرحلات الأساسيون")} value={staffing.primaryTripTeamLeaders} min={0} onChange={(value) => setStaffing(["primaryTripTeamLeaders"], value)} /><Toggle label={t("Backup staff allowed", "السماح بموظفي احتياط")} checked={staffing.backupStaffAllowed} onChange={(value) => setStaffing(["backupStaffAllowed"], value)} /><StringListField label={t("Suggested trip shift codes", "رموز شيفت الرحلات المقترحة")} value={staffing.suggestedTripShiftCodes} onChange={(value) => setStaffing(["suggestedTripShiftCodes"], value)} addLabel={t("Shift code", "رمز الشيفت")} t={t} /><Toggle label={t("Time overlap allowed", "السماح بتداخل الوقت")} checked={staffing.timeOverlap.allowed} onChange={(value) => setStaffing(["timeOverlap", "allowed"], value)} /><NumberField label={t("Overlap tolerance (minutes)", "هامش التداخل (دقائق)")} value={staffing.timeOverlap.toleranceMinutes} min={0} onChange={(value) => setStaffing(["timeOverlap", "toleranceMinutes"], value)} /><Toggle label={t("Availability required", "التوفر إلزامي")} checked={staffing.requireAvailability} onChange={(value) => setStaffing(["requireAvailability"], value)} /><Toggle label={t("Conflict warnings enabled", "تفعيل تحذيرات التعارض")} checked={staffing.conflictWarningsEnabled} onChange={(value) => setStaffing(["conflictWarningsEnabled"], value)} /><Toggle label={t("Override allowed", "التجاوز مسموح")} checked={staffing.override.allowed} onChange={(value) => setStaffing(["override", "allowed"], value)} /><Toggle label={t("Override reason required", "سبب التجاوز إلزامي")} checked={staffing.override.reasonRequired} onChange={(value) => setStaffing(["override", "reasonRequired"], value)} /><RolePicker label={t("Override roles", "أدوار التجاوز")} value={staffing.override.roles} onChange={(value) => setStaffing(["override", "roles"], value)} t={t} /></div></article>
  </>;
}

function WeekdayPicker({ value, onChange, t }) {
  const selected = list(value).map(Number); const names = [t("Sunday", "الأحد"), t("Monday", "الاثنين"), t("Tuesday", "الثلاثاء"), t("Wednesday", "الأربعاء"), t("Thursday", "الخميس"), t("Friday", "الجمعة"), t("Saturday", "السبت")];
  return <fieldset className={`${styles.choiceField} ${styles.wideField}`}><legend>{t("Required weekdays", "أيام الأسبوع المطلوبة")}</legend><div>{names.map((name, day) => <Toggle key={day} label={name} checked={selected.includes(day)} onChange={(checked) => onChange(checked ? [...selected, day].sort((a, b) => a - b) : selected.filter((item) => item !== day))} />)}</div></fieldset>;
}

function DateListField({ label, value, onChange, t }) {
  const [draft, setDraft] = useState(""); const values = list(value); const add = () => { if (draft && !values.includes(draft)) onChange([...values, draft]); setDraft(""); };
  return <fieldset className={`${styles.stringList} ${styles.wideField}`}><legend>{label}</legend><ol>{values.map((item, index) => <li key={`${item}-${index}`}><input type="date" value={item} aria-label={`${label} ${index + 1}`} onChange={(event) => onChange(values.map((entry, itemIndex) => itemIndex === index ? event.target.value : entry))} /><ActionButton type="button" className={styles.iconButton} onClick={() => onChange(values.filter((_, itemIndex) => itemIndex !== index))}>×</ActionButton></li>)}</ol><div className={styles.inlineAdd}><input type="date" value={draft} aria-label={t("New date", "تاريخ جديد")} onChange={(event) => setDraft(event.target.value)} /><ActionButton type="button" className="secondary" disabled={!draft} onClick={add}>{t("Add", "إضافة")}</ActionButton></div></fieldset>;
}

function DateRanges({ title, items, onChange, t }) {
  const add = () => onChange([...items, { label: "", startDate: today(), endDate: today() }]);
  return <section className={styles.nestedList}><SectionIntro title={title} action={<ActionButton type="button" className="secondary" onClick={add}>{t("Add period", "إضافة فترة")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.label}-${index}`}><TextField label={t("Label", "الاسم")} value={item.label} onChange={(value) => set("label", value)} /><TextField label={t("Start date", "تاريخ البداية")} type="date" value={item.startDate} onChange={(value) => set("startDate", value)} /><TextField label={t("End date", "تاريخ النهاية")} type="date" value={item.endDate} onChange={(value) => set("endDate", value)} /><div className={styles.rowButtons}><ActionButton type="button" className={styles.iconButton} disabled={index === 0} onClick={() => onChange(moveItem(items, index, -1))}>↑</ActionButton><ActionButton type="button" className={styles.iconButton} disabled={index === items.length - 1} onClick={() => onChange(moveItem(items, index, 1))}>↓</ActionButton><ActionButton type="button" className={styles.iconButton} onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}>×</ActionButton></div></div>; })}</section>;
}

function SuccessionSettings({ pageOwned, config, update, t }) {
  const succession = config.succession; const set = (key, value) => update(["succession", key], value);
  return <><SectionIntro pageOwned={pageOwned} title={t("Succession paths and competencies", "مسارات الخلافة والكفاءات")} text={t("Define promotion paths, cumulative evidence and the controlled catalogs used by development plans.", "حدد مسارات الترقية والأدلة التراكمية والقوائم المحكومة المستخدمة في خطط التطوير.")} />
    <SuccessionPaths items={succession.paths} onChange={(value) => set("paths", value)} t={t} />
    <Competencies items={succession.competencies} onChange={(value) => set("competencies", value)} t={t} />
    <OptionCatalog title={t("Readiness levels", "مستويات الجاهزية")} items={succession.readinessLevels} onChange={(value) => set("readinessLevels", value)} t={t} sortOrder codeLocked />
    <ReviewFrequencies items={succession.reviewFrequencyOptions} onChange={(value) => set("reviewFrequencyOptions", value)} t={t} />
    <OptionCatalog title={t("Development action types", "أنواع إجراءات التطوير")} items={succession.developmentActionTypes} onChange={(value) => set("developmentActionTypes", value)} t={t} allowAdd />
    <OptionCatalog title={t("Development statuses", "حالات التطوير")} items={succession.developmentStatuses} onChange={(value) => set("developmentStatuses", value)} t={t} codeLocked />
  </>;
}

function SuccessionPaths({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("PATH"), fromRole: "", toRole: "", enabled: false, cumulativeTemplateGroups: [] }]);
  return <article className={styles.configCard}><SectionIntro title={t("Succession paths", "مسارات الخلافة")} action={<ActionButton type="button" onClick={add}>{t("Add path", "إضافة مسار")}</ActionButton>} />{!items.length && <p className={styles.empty}>{t("No paths", "لا توجد مسارات")}</p>}{items.map((item, index) => { const replace = (next) => onChange(items.map((entry, itemIndex) => itemIndex === index ? next : entry)); const set = (key, value) => replace({ ...item, [key]: value }); return <section className={styles.nestedCard} key={`${item.code}-${index}`}><div className={styles.cardTitle}><h5>{item.fromRole && item.toRole ? `${item.fromRole} → ${item.toRole}` : item.code}</h5><ItemActions active={item.enabled} onActive={(value) => set("enabled", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Path code", "رمز المسار")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("From role", "من دور")} value={item.fromRole} onChange={(value) => set("fromRole", value)} /><TextField label={t("To role", "إلى دور")} value={item.toRole} onChange={(value) => set("toRole", value)} /><StringListField label={t("Cumulative template groups", "مجموعات القوالب التراكمية")} value={item.cumulativeTemplateGroups} onChange={(value) => set("cumulativeTemplateGroups", value)} addLabel={t("Template group", "مجموعة قوالب")} t={t} /></div></section>; })}</article>;
}

function Competencies({ items, onChange, t }) {
  const add = () => onChange([...items, { templateCode: itemCode("COMPETENCY_TEMPLATE"), code: itemCode("COMPETENCY"), group: "", label: "", labelAr: "", requiredLevel: 0, order: (items.length + 1) * 10, active: true, evidenceRequired: false, operationalReportsQualifyAsEvidence: false, practicalAssignmentTypes: [] }]);
  return <article className={styles.configCard}><SectionIntro title={t("Competency templates", "قوالب الكفاءات")} action={<ActionButton type="button" onClick={add}>{t("Add competency", "إضافة كفاءة")}</ActionButton>} />{items.map((item, index) => { const replace = (next) => onChange(items.map((entry, itemIndex) => itemIndex === index ? next : entry)); const set = (key, value) => replace({ ...item, [key]: value }); return <section className={styles.nestedCard} key={`${item.templateCode}-${item.code}-${index}`}><div className={styles.cardTitle}><div><span>{item.templateCode}</span><h5>{item.label || item.code}</h5></div><ItemActions active={item.active} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1, "order"))} onDown={() => onChange(moveItem(items, index, 1, "order"))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div><div className={styles.fieldGrid}><TextField label={t("Template code", "رمز القالب")} value={item.templateCode} onChange={(value) => set("templateCode", value)} /><TextField label={t("Competency code", "رمز الكفاءة")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("Group", "المجموعة")} value={item.group} onChange={(value) => set("group", value)} /><TextField label={t("English label", "الاسم بالإنجليزية")} value={item.label} onChange={(value) => set("label", value)} /><TextField label={t("Arabic label", "الاسم بالعربية")} value={item.labelAr} onChange={(value) => set("labelAr", value)} /><NumberField label={t("Required level", "المستوى المطلوب")} value={item.requiredLevel} min={0} max={100} onChange={(value) => set("requiredLevel", value)} /><NumberField label={t("Order", "الترتيب")} value={item.order} min={1} onChange={(value) => set("order", value)} /><Toggle label={t("Evidence required", "الدليل إلزامي")} checked={item.evidenceRequired} onChange={(value) => set("evidenceRequired", value)} /><Toggle label={t("Operational reports qualify as evidence", "التقارير التشغيلية مؤهلة كدليل")} checked={item.operationalReportsQualifyAsEvidence} onChange={(value) => set("operationalReportsQualifyAsEvidence", value)} /><StringListField label={t("Practical assignment types", "أنواع التكليف العملي")} value={item.practicalAssignmentTypes} onChange={(value) => set("practicalAssignmentTypes", value)} addLabel={t("Assignment type", "نوع التكليف")} t={t} /></div></section>; })}</article>;
}

function OptionCatalog({ title, items, onChange, t, allowAdd = false, sortOrder = false, codeLocked = false }) {
  const add = () => onChange([...items, { code: itemCode("OPTION"), label: "", active: true, ...(sortOrder ? { sortOrder: (items.length + 1) * 10 } : {}) }]);
  return <article className={styles.configCard}><SectionIntro title={title} action={allowAdd ? <ActionButton type="button" onClick={add}>{t("Add option", "إضافة خيار")}</ActionButton> : null} /><div className={styles.catalogList}>{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.code}-${index}`}><TextField label={t("Code", "الرمز")} value={item.code} disabled={codeLocked} onChange={(value) => set("code", value)} /><TextField label={t("Label", "الاسم")} value={item.label} onChange={(value) => set("label", value)} />{sortOrder && <NumberField label={t("Order", "الترتيب")} value={item.sortOrder} min={0} onChange={(value) => set("sortOrder", value)} />}<Toggle label={t("Active", "مفعل")} checked={item.active} onChange={(value) => set("active", value)} /><ItemActions active={item.active} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1, sortOrder ? "sortOrder" : undefined))} onDown={() => onChange(moveItem(items, index, 1, sortOrder ? "sortOrder" : undefined))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div>; })}</div></article>;
}

function ReviewFrequencies({ items, onChange, t }) {
  const add = () => onChange([...items, { code: itemCode("FREQUENCY"), label: "", months: 1, active: true }]);
  return <article className={styles.configCard}><SectionIntro title={t("Review frequencies", "دوريات المراجعة")} action={<ActionButton type="button" onClick={add}>{t("Add frequency", "إضافة دورية")}</ActionButton>} />{items.map((item, index) => { const set = (key, value) => onChange(items.map((entry, itemIndex) => itemIndex === index ? { ...entry, [key]: value } : entry)); return <div className={styles.collectionRow} key={`${item.code}-${index}`}><TextField label={t("Code", "الرمز")} value={item.code} onChange={(value) => set("code", value)} /><TextField label={t("Label", "الاسم")} value={item.label} onChange={(value) => set("label", value)} /><NumberField label={t("Months", "الأشهر")} value={item.months} min={1} max={120} onChange={(value) => set("months", value)} /><Toggle label={t("Active", "مفعل")} checked={item.active} onChange={(value) => set("active", value)} /><ItemActions active={item.active} onActive={(value) => set("active", value)} onUp={() => onChange(moveItem(items, index, -1))} onDown={() => onChange(moveItem(items, index, 1))} disableUp={index === 0} disableDown={index === items.length - 1} t={t} /></div>; })}</article>;
}

function PermissionSettings({ pageOwned, config, update, t }) {
  const permissions = config.permissions;
  const roleFields = [["settingsRoles", t("May change Performance & Reports settings", "يمكنه تغيير إعدادات الأداء والتقارير")], ["reportProposeRoles", t("May propose reports", "يمكنه اقتراح التقارير")], ["reportApproveRoles", t("May approve reports", "يمكنه اعتماد التقارير")], ["adjustmentProposeRoles", t("May propose adjustments", "يمكنه اقتراح التعديلات")], ["adjustmentApproveRoles", t("May approve adjustments", "يمكنه اعتماد التعديلات")], ["adjustmentRejectRoles", t("May reject adjustments", "يمكنه رفض التعديلات")], ["adjustmentReopenRoles", t("May reopen adjustments", "يمكنه إعادة فتح التعديلات")], ["suitabilityOverrideRoles", t("May override suitability", "يمكنه تجاوز الملاءمة")], ["staffingOverrideRoles", t("May override staffing", "يمكنه تجاوز التوظيف")]];
  return <><SectionIntro pageOwned={pageOwned} title={t("Permissions and approvals", "الصلاحيات والاعتمادات")} text={t("Permissions are limited to Administrator and Manager. Authentication determines who publishes; names cannot be entered here as approval.", "الصلاحيات مقصورة على المسؤول والمدير. تحدد جلسة الدخول من ينشر؛ ولا يمكن إدخال اسم هنا باعتباره اعتمادًا.")} /><article className={styles.configCard}><div className={styles.fieldGrid}>{roleFields.map(([key, label]) => <RolePicker key={key} label={label} value={permissions[key]} onChange={(value) => update(["permissions", key], value)} t={t} />)}<Toggle label={t("Second reviewer is required when the draft author is linked to an employee", "يلزم مراجع ثانٍ عندما يكون مؤلف المسودة مرتبطًا بموظف")} hint={t("Required security policy", "سياسة أمنية إلزامية")} checked disabled onChange={() => {}} /></div></article></>;
}

function ActionPanel({ title, reason, setReason, effectiveFrom, setEffectiveFrom, draft, requiresSecondReviewer = false, busy, confirm, cancel, confirmLabel, t, danger = false }) {
  const linkedDraft = Boolean(draft?.createdByEmployeeId);
  return <section className={styles.nestedCard} aria-label={title}><div className={styles.sectionIntro}><div><h4>{title}</h4><p>{t("This creates a dated audit event. Existing records keep the version captured when they were created.", "ينشئ هذا حدث تدقيق مؤرخًا. تحتفظ السجلات الحالية بالإصدار المحفوظ عند إنشائها.")}</p></div></div>{requiresSecondReviewer && linkedDraft && <p className={styles.previewNote} role="status">{t("This draft was saved by an account linked to an employee. A different authorized administrator or manager, linked to a different employee, must publish it from their own session.", "حُفظت هذه المسودة بواسطة حساب مرتبط بموظف. يجب أن ينشرها مسؤول أو مدير مخول مختلف ومرتبط بموظف آخر من جلسته الخاصة.")}</p>}<div className={styles.fieldGrid}><TextField label={t("Effective date", "تاريخ السريان")} type="date" value={effectiveFrom} onChange={setEffectiveFrom} /><TextAreaField label={t("Audit reason", "سبب التدقيق")} value={reason} onChange={setReason} placeholder={t("Explain why this effective change is needed", "اشرح سبب الحاجة إلى هذا التغيير الساري")} /></div><div className={styles.actionButtons}><ActionButton type="button" className={danger ? "danger" : undefined} disabled={busy || !reason.trim() || !effectiveFrom} onClick={confirm}>{confirmLabel}</ActionButton><ActionButton type="button" className="secondary" disabled={busy} onClick={cancel}>{t("Cancel", "إلغاء")}</ActionButton></div></section>;
}

function HistoryPanel({ state, t }) {
  const history = state?.history || [];
  return <section className={`panel ${styles.saveArea}`} aria-label={t("Version history", "سجل الإصدارات")}><SectionIntro title={t("Version history", "سجل الإصدارات")} text={t("Published versions and branch reset events remain available for audit.", "تظل الإصدارات المنشورة وأحداث إعادة ضبط الفرع متاحة للتدقيق.")} />
    {state?.draft && <article className={styles.nestedCard}><div className={styles.cardTitle}><div><span>{t("CURRENT DRAFT", "المسودة الحالية")}</span><h4>{t(`Revision ${state.draft.revision}`, `المراجعة ${state.draft.revision}`)}</h4></div><span className={styles.versionChip}>{state.draft.updatedAt ? new Date(state.draft.updatedAt).toLocaleString() : "—"}</span></div><div className={styles.previewMeta}><span><b>{t("Reason", "السبب")}</b>{state.draft.reason || "—"}</span><span><b>{t("Created by", "أنشأها")}</b>{state.draft.createdBy || state.draft.updatedBy || "—"}</span><span><b>{t("Based on revision", "مبنية على المراجعة")}</b>{state.draft.basedOnRevision ?? "—"}</span><span><b>{t("Global base", "الأساس العام")}</b>{state.draft.baseGlobalRevision ?? "—"}</span></div></article>}
    {!history.length ? <p className={styles.emptyState}>{t("No publication history for this scope.", "لا يوجد سجل نشر لهذا النطاق.")}</p> : <div className={styles.catalogList}>{history.map((entry, index) => { const published = entry.type === "PUBLISHED"; return <article className={styles.nestedCard} key={entry.id || `${entry.type}-${index}`}><div className={styles.cardTitle}><div><span>{published ? t("PUBLISHED VERSION", "إصدار منشور") : t("BRANCH RESET", "إعادة ضبط الفرع")}</span><h4>{published && entry.version != null ? `v${entry.version}` : t("Returned to global", "العودة إلى الإعداد العام")}</h4></div><span className={styles.versionChip}>{entry.effectiveFrom || "—"}</span></div><div className={styles.previewMeta}><span><b>{t("Reason", "السبب")}</b>{entry.reason || "—"}</span><span><b>{t("Published / reset by", "نشر / أعاد الضبط")}</b>{entry.publishedBy || entry.resetBy || "—"}</span><span><b>{t("Recorded", "سُجل في")}</b>{entry.publishedAt || entry.resetAt ? new Date(entry.publishedAt || entry.resetAt).toLocaleString() : "—"}</span>{entry.baseGlobalRef && <span><b>{t("Global base version", "إصدار الأساس العام")}</b>{entry.baseGlobalRef.version ?? "—"}</span>}</div></article>; })}</div>}
  </section>;
}

function SourceNormalization({value,onChange,t}) { const data={...NORMALIZATION_DEFAULTS,...value};return <section className={styles.configCard}><h4>{t('Source scoring rubric','قواعد درجات المصدر')}</h4><p>{t('Only finalized attendance, reviewed evaluations and resolved feedback are scored. These editable values are captured with the published version.','تُحتسب درجات الحضور النهائي والتقييمات المراجعة وملاحظات الضيوف المغلقة فقط. تحفظ هذه القيم القابلة للتعديل مع الإصدار المنشور.')}</p><div className={styles.fieldGrid}>{[['lateGraceMinutes',t('Lateness grace (minutes)','سماح التأخير (دقائق)')],['earlyLeaveGraceMinutes',t('Early departure grace (minutes)','سماح الخروج المبكر (دقائق)')],['onTimeScore',t('On-time suitability score','درجة الالتزام للملاءمة')],['lateScore',t('Late suitability score','درجة التأخير للملاءمة')],['absenceScore',t('Absence suitability score','درجة الغياب للملاءمة')],['guestRatingMinimum',t('Minimum guest rating','أدنى تقييم للضيف')],['guestRatingMaximum',t('Maximum guest rating','أقصى تقييم للضيف')]].map(([key,label])=><NumberField key={key} label={label} value={data[key]} min={0} onChange={next=>onChange({...data,[key]:next})}/>)}</div></section>; }

